/**
 * Gramian Angular Field (GAF) Transformation
 * Converts time series to polar coordinates and calculates GAF matrix.
 */
export const calculateGAF = (data: number[]) => {
  const min = Math.min(...data);
  const max = Math.max(...data);

  // Normalize to [-1, 1]
  const normalized = data.map(x => (2 * (x - min) / (max - min)) - 1);

  // Polar coordinates: cos(phi) = normalized[i]
  const phis = normalized.map(x => Math.acos(x));

  const size = data.length;
  const matrix: number[][] = Array(size).fill(0).map(() => Array(size).fill(0));

  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      // GASF: cos(phi_i + phi_j) = cos(phi_i)cos(phi_j) - sin(phi_i)sin(phi_j)
      matrix[i][j] = Math.cos(phis[i] + phis[j]);
    }
  }

  return matrix;
};

/**
 * Markov Transition Field (MTF) simplification
 */
export const calculateMTF = (data: number[], bins = 8) => {
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min;

  const states = data.map(x => Math.min(Math.floor(((x - min) / range) * bins), bins - 1));
  const size = data.length;
  const matrix: number[][] = Array(size).fill(0).map(() => Array(size).fill(0));

  // Create transition matrix first
  const transition = Array(bins).fill(0).map(() => Array(bins).fill(0));
  for (let i = 0; i < states.length - 1; i++) {
    transition[states[i]][states[i+1]]++;
  }

  // Row-normalize
  for (let i = 0; i < bins; i++) {
    const sum = transition[i].reduce((a, b) => a + b, 0);
    if (sum > 0) transition[i] = transition[i].map(x => x / sum);
  }

  // Map back to temporal matrix
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      matrix[i][j] = transition[states[i]][states[j]];
    }
  }

  return matrix;
};

export const generateSyntheticLOB = (midPrice: number, spread = 0.5) => {
  const levels = 20;
  const bids: any[] = [];
  const asks: any[] = [];

  for (let i = 0; i < levels; i++) {
    const bidPrice = midPrice - (spread / 2) - (i * 0.1);
    const askPrice = midPrice + (spread / 2) + (i * 0.1);

    // Add some "Spoofing" or "Iceberg" anomalies
    const isAnomalous = Math.random() > 0.9;

    bids.push({ price: bidPrice, size: (isAnomalous ? 100 : Math.random() * 10), isAnomalous });
    asks.push({ price: askPrice, size: (isAnomalous ? 100 : Math.random() * 10), isAnomalous });
  }

  return { bids, asks };
};

