import React, { useRef, useEffect } from 'react';
import * as d3 from 'd3';
import { calculateGAF, calculateMTF } from '../utils/math';

interface RetinaDisplayProps {
  data: number[];
  type: 'GAF' | 'MTF' | 'Recurrence';
}

const RetinaDisplay: React.FC<RetinaDisplayProps> = ({ data, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current || data.length === 0) return;

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const matrix = type === 'GAF' ? calculateGAF(data) : calculateMTF(data);
    const size = matrix.length;
    const canvasSize = 400;
    const cellSize = canvasSize / size;

    canvasRef.current.width = canvasSize;
    canvasRef.current.height = canvasSize;

    // Drawing the heatmap matrix
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size; j++) {
        const val = matrix[i][j];
        // Scale val for visibility
        const intensity = Math.floor(((val + 1) / 2) * 255);

        if (type === 'GAF') {
          // Heatmap from cool to warm
          ctx.fillStyle = `rgb(${intensity}, ${Math.floor(intensity / 2)}, ${255 - intensity})`;
        } else {
          // Probability matrix in emerald
          ctx.fillStyle = `rgba(16, 185, 129, ${val * 1.5})`;
        }

        ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
      }
    }

    // Add YOLO-style bounding box simulation (Visualizing "The Retina" finding patterns)
    if (Math.random() > 0.5) {
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.strokeRect(50, 80, 120, 120);

      ctx.fillStyle = '#22c55e';
      ctx.font = '10px JetBrains Mono';
      ctx.fillText('PATTERN: WYCKOFF_ACCUM (0.92)', 50, 75);
    }

  }, [data, type]);

  return (
    <div className="flex flex-col items-center bg-[#0d0d0d] p-4 rounded-lg border border-white/5">
      <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4">
        {type} Visual Transformation
      </h3>
      <canvas ref={canvasRef} className="rounded cursor-crosshair shadow-2xl" />
      <div className="mt-4 text-[10px] text-gray-500 mono text-center max-w-[300px]">
        {type === 'GAF' 
          ? 'Preserving temporal correlations using Polar Coordinate transformations.' 
          : 'Mapping state transition probabilities into temporal heatmaps.'}
      </div>
    </div>
  );
};

export default RetinaDisplay;

