/**
 * Gramian Angular Field (GAF) Transformation
 * Converts time series to polar coordinates and calculates GAF matrix.
 */
export const calculateGAF = (data: number[]) => {
  if (data.length === 0) return [];
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1; // Avoid division by zero

  // Normalize to [-1, 1]
  const normalized = data.map(x => (2 * (x - min) / range) - 1);

  // Polar coordinates: cos(phi) = normalized[i]
  const phis = normalized.map(x => Math.acos(Math.max(-1, Math.min(1, x))));

  const size = data.length;
  const matrix: number[][] = Array(size).fill(0).map(() => Array(size).fill(0));

  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      // GASF: cos(phi_i + phi_j) = cos(phi_i)cos(phi_j) - sin(phi_i)sin(phi_j)
      matrix[i][j] = Math.cos(phis[i] + phis[j]);
    }
  }

  return matrix;
};

/**
 * Markov Transition Field (MTF) simplification
 */
export const calculateMTF = (data: number[], bins = 8) => {
  if (data.length === 0) return [];
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1; // Avoid division by zero

  const states = data.map(x => Math.min(Math.floor(((x - min) / range) * bins), bins - 1));
  const size = data.length;
  const matrix: number[][] = Array(size).fill(0).map(() => Array(size).fill(0));

  // Create transition matrix first
  const transition = Array(bins).fill(0).map(() => Array(bins).fill(0));
  for (let i = 0; i < states.length - 1; i++) {
    const s1 = states[i];
    const s2 = states[i+1];
    // Safeguard indices just in case
    if (!isNaN(s1) && !isNaN(s2) && transition[s1]) {
      transition[s1][s2]++;
    }
  }

  // Row-normalize
  for (let i = 0; i < bins; i++) {
    const sum = transition[i].reduce((a: number, b: number) => a + b, 0);
    if (sum > 0) transition[i] = transition[i].map((x: number) => x / sum);
  }

  // Map back to temporal matrix
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      const s_i = states[i];
      const s_j = states[j];
      if (!isNaN(s_i) && !isNaN(s_j) && transition[s_i]) {
        matrix[i][j] = transition[s_i][s_j];
      } else {
        matrix[i][j] = 0;
      }
    }
  }

  return matrix;
};

