interface RetinaDisplayProps {
  data: number[];
  type: 'GAF' | 'MTF' | 'Recurrence';
}

const RetinaDisplay: React.FC<RetinaDisplayProps> = ({ data, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current || data.length === 0) return;

    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const matrix = type === 'GAF' ? calculateGAF(data) : calculateMTF(data);
    const size = matrix.length;
    const canvasSize = 400;
    const cellSize = canvasSize / size;

    canvasRef.current.width = canvasSize;
    canvasRef.current.height = canvasSize;

    // Drawing the heatmap matrix
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size; j++) {
        const val = matrix[i][j];
        // Scale val for visibility
        const intensity = Math.floor(((val + 1) / 2) * 255);

        if (type === 'GAF') {
          // Heatmap from cool to warm
          ctx.fillStyle = `rgb(${intensity}, ${Math.floor(intensity / 2)}, ${255 - intensity})`;
        } else {
          // Probability matrix in emerald
          ctx.fillStyle = `rgba(16, 185, 129, ${val * 1.5})`;
        }

        ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
      }
    }

    // Computer Vision Pattern Detection Overlay
    // Only show if we have enough data and randomly for simulation
    if (data.length > 20 && Math.random() > 0.4) {
      const patterns = [
        { name: 'WYCKOFF_ACCUM', conf: 0.92 },
        { name: 'HEAD_SHOULDERS', conf: 0.88 },
        { name: 'BULL_FLAG', conf: 0.95 },
        { name: 'DOUBLE_BOTTOM', conf: 0.84 }
      ];
      const pattern = patterns[Math.floor(Math.random() * patterns.length)];

      const boxX = 60 + Math.random() * 40;
      const boxY = 60 + Math.random() * 40;
      const boxW = 150;
      const boxH = 150;

      // Draw Bounding Box
      ctx.strokeStyle = '#22c55e';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.strokeRect(boxX, boxY, boxW, boxH);

      // Reset dash for text background if needed, but we'll use clean text
      ctx.setLineDash([]);

      // Draw Label Background for better legibility
      ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
      ctx.fillRect(boxX, boxY - 25, 180, 20);

      // Draw Pattern Text and Confidence
      ctx.fillStyle = '#22c55e';
      ctx.font = 'bold 11px "JetBrains Mono"';
      ctx.fillText(`${pattern.name} (${pattern.conf.toFixed(2)})`, boxX + 5, boxY - 11);

      // Optional: Draw anchor points
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(boxX - 3, boxY - 3, 6, 6);
      ctx.fillRect(boxX + boxW - 3, boxY - 3, 6, 6);
      ctx.fillRect(boxX - 3, boxY + boxH - 3, 6, 6);
      ctx.fillRect(boxX + boxW - 3, boxY + boxH - 3, 6, 6);
    }

  }, [data, type]);

  return (
    <div className="flex flex-col items-center bg-[#0d0d0d] p-4 rounded-lg border border-white/5">
      <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4">
