import { TokenData } from '../types';

/**
 * Note: Free API has rate limits. 
 * Using basic public endpoints for simplicity.
 */
export const fetchTokenByAddress = async (address: string): Promise<TokenData | null> => {
  try {
    // In a real app, we'd need to identify the platform (e.g., ethereum, solana)
    // For this demo, we assume Ethereum/Universal search via search endpoint
    const searchRes = await fetch(`https://api.coingecko.com/api/v3/search?query=${address}`);
    const searchData = await searchRes.json();

    if (!searchData.coins || searchData.coins.length === 0) return null;

    const coinId = searchData.coins[0].id;
    const priceRes = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${coinId}&vs_currencies=usd&include_market_cap=true&include_24hr_vol=true&include_24hr_change=true`);
    const priceData = await priceRes.json();

    const coin = priceData[coinId];
    return {
      id: coinId,
      symbol: searchData.coins[0].symbol,
      name: searchData.coins[0].name,
      priceUsd: coin.usd,
      priceChange24h: coin.usd_24h_change,
      marketCap: coin.usd_market_cap,
      volume24h: coin.usd_24h_vol,
      image: searchData.coins[0].large
    };
  } catch (err) {
    console.error("CoinGecko Fetch Error:", err);
    return null;
  }
};

