// Initialize with the API key from environment variables directly.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getMarketAnalysis = async (visualPatterns: string, quantData: any) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `CRITICAL MISSION: Provide a direct trading signal.

      MARKET SNAPSHOT:
      - Asset: ${quantData.token}
      - Current Price: $${quantData.price}
      - Visual Symmetries (GAF/MTF): ${visualPatterns}
      - Market Microstructure: L3 Order Book shows ${quantData.volatility} activity.

      REQUIRED FORMAT:
      1. ACTION: [BUY / SELL / HOLD-WAIT] (Must be one of these)
      2. TIMING: [EXECUTE NOW / WAIT FOR PULLBACK / WAIT FOR BREAKOUT]
      3. REASONING: One sentence on the visual symmetry detected.
      4. TARGETS: Entry, Take Profit, and Stop Loss levels based on price.

      Tone: Authoritative CQIO. No disclaimers. Give me the signal.`,
      config: {
        systemInstruction: "You are 'The Eye', a high-conviction proprietary trading AI. You do not give vague advice. You provide specific entry and exit directives based on computer vision patterns in financial data. Your goal is to maximize P&L for a retail user with clear instructions.",
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 4000 }
      }
    });
    return response.text;
  } catch (err: any) {
    console.error("Gemini Error:", err);
    if (err.message?.includes("Region not supported")) {
      return "ERROR: The Eye is currently restricted in your geographic region. Please use a supported gateway or check API configuration.";
    }
    return "The Eye is momentarily blinded. Retrying connection to neural cluster...";
  }
};

