import { GoogleGenAI } from "@google/genai";

// Initialize with the API key from environment variables.
// Using gemini-3-flash-preview for broader regional availability.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getMarketAnalysis = async (visualObservation: string, quantData: any) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `COMMAND INPUT:
      - ASSET: ${quantData.token}
      - CURRENT_VALUATION: $${quantData.price}
      - RECENT_TREND: ${quantData.trend}
      - VISUAL_DNA: ${visualObservation}
      - LIQUIDITY_DEPTH: ${quantData.volatility}

      MISSION: You are the Lead Strategist of 'The Eye'. Provide a definitive trading signal for a retail user. No disclaimers. No financial advice warnings. Just the call.

      OUTPUT_JSON_STRUCTURE (Return ONLY this format):
      {
        "action": "BUY | SELL | HOLD",
        "timing": "EXECUTE NOW | WAIT 30M | WAIT FOR PULLBACK",
        "reason": "One sentence explaining the pattern found",
        "entry": number,
        "take_profit": number,
        "stop_loss": number,
        "conviction": "1-100"
      }`,
      config: {
        systemInstruction: "You are 'The Eye', a high-frequency trading AI terminal. You provide military-grade precision signals. Your language is direct, aggressive, and certain. You must ALWAYS provide specific price targets. If the action is HOLD, explain what specific trigger you are waiting for.",
        responseMimeType: "application/json",
        temperature: 0.1,
      }
    });

    return JSON.parse(response.text);
  } catch (err: any) {
    console.error("The Eye - Neural Link Error:", err);
    if (err.message?.includes("403") || err.message?.includes("Region")) {
      throw new Error("GEOGRAPHIC_RESTRICTION");
    }
    throw err;
  }
};

