    if (prices.length === 0) {
      setPrices(Array(32).fill(65000).map(p => p + (Math.random() - 0.5) * 100));
    }
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setPrices(prev => {
        const last = prev.length > 0 ? prev[prev.length - 1] : (currentToken?.priceUsd || 65000);
        const volatility = 0.0008;
        const next = last + (Math.random() - 0.5) * (last * volatility);
        return [...prev, next].slice(-32);
      });
      setLob(prevLob => {
        const mid = prevLob.bids.length > 0 ? (prevLob.bids[0].price + prevLob.asks[0].price) / 2 : (currentToken?.priceUsd || 65000);
        return generateSyntheticLOB(mid + (Math.random() - 0.5) * 2);
      });
      setLatency(0.3 + Math.random() * 0.2);
    }, 3000);
    return () => clearInterval(interval);
