      if (data) {
        setCurrentToken(data);
        const historicalContext = Array(32).fill(0).map((_, i) => data.priceUsd + (Math.random() - 0.5) * (data.priceUsd * 0.02));
        setPrices(historicalContext); 
        setSignal(null);
      } else {
        setError("Token not found. Verify contract address.");
      }
    } catch (err) {
      setError("Market data fetch failed.");
    }
    setIsSearching(false);
