import React, { useState, useEffect } from 'react';
import { 
  ShieldAlert, Activity, Zap, Globe, Search, Cpu, RefreshCw, Target, 
  AlertCircle, TrendingUp, Map as MapIcon, Share2, Box, BarChart3, 
  Waves, Filter, Wallet, ArrowUpRight, ArrowDownRight, Menu, X, Rocket
} from 'lucide-react';
import { ViewState, TokenData } from './types';
import { generateMempoolData, generateTopographyData, generateWalletGraph, generateMetricChartData } from './utils/math';
import { getMEVAnalysis } from './services/geminiService';
import { fetchTokenByAddress } from './services/coingeckoService';
import ProfitSimulator from './components/ProfitSimulator';
import RetinaDisplay from './components/RetinaDisplay';
import WalletGraph from './components/WalletGraph';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<ViewState>(ViewState.MEMPOOL);
  const [strategy, setStrategy] = useState<'SCALP' | 'SWING' | 'AGGRESSIVE'>('SCALP');
  const [mempool, setMempool] = useState<any[]>([]);
  const [topoData, setTopoData] = useState<any[]>([]);
  const [graphData, setGraphData] = useState<any>(null);
  const [mcChart, setMcChart] = useState<number[]>([]);
  const [volChart, setVolChart] = useState<number[]>([]);
  const [currentToken, setCurrentToken] = useState<TokenData | null>(null);
  const [tradingCapital, setTradingCapital] = useState(5000);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const interval = setInterval(() => {
      const baseGas = 30 + Math.random() * 20;
      setMempool(generateMempoolData(baseGas));
      if (currentToken) {
        setTopoData(generateTopographyData(currentToken.priceUsd));
        setMcChart(prev => [...prev.slice(-19), currentToken.marketCap * (1 + (Math.random() - 0.5) * 0.01)]);
        setVolChart(prev => [...prev.slice(-19), currentToken.volume24h * (1 + (Math.random() - 0.5) * 0.03)]);
      }
    }, 3000);
    return () => clearInterval(interval);
  }, [currentToken]);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;
    setIsSearching(true);
    setError(null);
    const data = await fetchTokenByAddress(searchQuery);
    if (data) {
      setCurrentToken(data);
      setGraphData(generateWalletGraph());
      setTopoData(generateTopographyData(data.priceUsd));
      setMcChart(generateMetricChartData(data.marketCap));
      setVolChart(generateMetricChartData(data.volume24h));
      setReport(null);
    } else {
      setError("Asset contract verification failed. Check address integrity.");
    }
    setIsSearching(false);
  };

  const runDeFiScan = async () => {
    if (!currentToken) return;
    setIsAnalyzing(true);
    setError(null);
    try {
      const visualContext = activeView === ViewState.MEMPOOL 
        ? "Mempool Energy Spectrogram shows high-intensity GAF patterns indicating retail-driven accumulation."
        : activeView === ViewState.TOPOGRAPHY
        ? "Liquidity Topology reveals massive buy walls at immediate supports."
        : "Wallet Constellation scan has identified 3 distinct math bot clusters funneling liquidity.";

      const res = await getMEVAnalysis(visualContext, {
        mode: activeView,
        token: `${currentToken.name} (${currentToken.symbol})`,
        gas: 35,
        price: currentToken.priceUsd,
        marketCap: currentToken.marketCap,
        volume: currentToken.volume24h,
        strategy: strategy
      });
      setReport(res);
    } catch (err) {
      setError("AI Signal Interrupted. Check your network co-location status.");
    }
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen bg-[#050505] text-[#d1d1d1] flex flex-col lg:flex-row font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <nav className="w-full lg:w-20 lg:min-h-screen border-b lg:border-r border-white/5 flex lg:flex-col items-center justify-between lg:justify-start p-4 lg:py-8 gap-10 bg-[#080808] z-50">
        <div className="p-2.5 bg-red-600 rounded-xl text-white shadow-[0_0_25px_rgba(220,38,38,0.3)]">
          <ShieldAlert size={24} />
        </div>

        <div className="flex lg:flex-col gap-4 lg:gap-8">
          {[
            { id: ViewState.MEMPOOL, icon: Activity, label: 'Retina' },
            { id: ViewState.TOPOGRAPHY, icon: MapIcon, label: 'Topo' },
            { id: ViewState.GRAPH, icon: Share2, label: 'Graph' }
          ].map((item) => (
            <button 
              key={item.id}
              onClick={() => setActiveView(item.id)}
              className={`p-3.5 rounded-2xl transition-all flex flex-col items-center gap-1 ${activeView === item.id ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(239,68,68,0.5)]' : 'text-gray-600 hover:text-white hover:bg-white/5'}`}
            >
              <item.icon size={22} />
              <span className="text-[7px] font-black uppercase lg:hidden mt-1">{item.label}</span>
            </button>
          ))}
        </div>
      </nav>

      {/* MAIN CONTENT */}
      <main className="flex-1 flex flex-col min-w-0">
        {/* TOP BAR */}
        <header className="h-auto lg:h-20 border-b border-white/5 flex flex-col lg:flex-row items-center px-4 lg:px-8 py-4 lg:py-0 justify-between bg-[#080808] gap-4">
          <div className="flex flex-col lg:flex-row items-center gap-4 w-full lg:w-auto">
            <form onSubmit={handleSearch} className="relative w-full lg:w-96">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
              <input 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Paste Contract (ETH/SOL)..."
                className="w-full bg-black border border-white/10 rounded-xl py-3 pl-12 pr-4 text-xs mono focus:border-red-500 outline-none transition-all shadow-inner"
              />
              {isSearching && <RefreshCw className="absolute right-4 top-1/2 -translate-y-1/2 text-red-500 animate-spin" size={16} />}
            </form>
            <div className="flex items-center gap-2 bg-white/5 px-4 py-2.5 rounded-xl border border-white/5 w-full lg:w-auto">
              <Filter size={16} className="text-gray-500" />
              <select 
                value={strategy}
                onChange={(e) => setStrategy(e.target.value as any)}
                className="bg-transparent text-[11px] font-black uppercase tracking-widest text-gray-400 outline-none w-full cursor-pointer"
              >
                <option value="SCALP">Scalp Strategy</option>
                <option value="SWING">Swing Strategy</option>
                <option value="AGGRESSIVE">Degen / Aggressive</option>
              </select>
            </div>
          </div>

          {currentToken && (
            <div className="flex items-center gap-5 bg-gradient-to-r from-red-500/10 to-transparent px-6 py-2 rounded-2xl border border-red-500/20 w-full lg:w-auto animate-fade-in shadow-lg">
              <img src={currentToken.image} className="w-8 h-8 rounded-full border border-white/10 shadow-lg" alt={currentToken.name} />
              <div className="flex flex-col">
                <div className="text-[9px] text-red-500 font-black uppercase tracking-widest mb-0.5">{currentToken.name}</div>
                <div className="flex items-center gap-3">
                  <span className="text-sm font-black text-white">{currentToken.symbol}</span>
                  <span className="text-lg font-black text-green-400 mono">${currentToken.priceUsd.toLocaleString(undefined, { minimumFractionDigits: 6 })}</span>
                </div>
              </div>
            </div>
          )}
        </header>

        {/* VIEWPORT AREA */}
        <div className="flex-1 p-4 lg:p-8 grid grid-cols-12 gap-6 lg:gap-8 overflow-y-auto lg:overflow-hidden bg-[radial-gradient(circle_at_center,_#0a0a0a_0%,_#050505_100%)]">

          {/* LEFT COLUMN: VISUALS */}
          <div className="col-span-12 lg:col-span-8 flex flex-col gap-6">
            <section className="flex-1 min-h-[500px] bg-black/60 rounded-[40px] border border-white/5 relative overflow-hidden shadow-2xl backdrop-blur-3xl group">
              {/* Dynamic Header */}
              <div className="absolute top-8 left-8 z-30 flex flex-col gap-1">
                <h1 className="text-3xl font-black uppercase tracking-tighter text-white drop-shadow-lg">
                  {activeView === ViewState.MEMPOOL ? 'Energy Retina' : activeView === ViewState.TOPOGRAPHY ? 'Liquidity Topology' : 'Graph Topology'}
                </h1>
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_10px_rgba(239,68,68,1)]" />
                  <span className="text-[10px] mono text-gray-500 tracking-[0.4em] uppercase">SYSTEMS_ONLINE // {activeView}</span>
                </div>
              </div>

              {/* View Rendering */}
              <div className="absolute inset-0 flex items-center justify-center p-8">
                {activeView === ViewState.MEMPOOL && (
                  <RetinaDisplay data={mempool.map(tx => tx.gasPrice)} type="GAF" />
