                {activeView === ViewState.TOPOGRAPHY && (
                  <div className="w-full flex flex-col items-center gap-8 animate-fade-in">
                    <div className="w-full flex items-end justify-center gap-3 h-80 px-12 relative">
                      {topoData.map((tick, i) => (
                        <div 
                          key={i} 
                          className={`flex-1 rounded-t-2xl transition-all duration-1000 relative group/bar ${tick.isPeak ? 'bg-gradient-to-t from-blue-600 to-cyan-400 shadow-[0_0_40px_rgba(37,99,235,0.4)]' : 'bg-white/5'}`}
                          style={{ height: `${tick.depth}%` }}
                        >
                           {/* Animated "Water" Shimmer */}
                           {tick.isPeak && <div className="absolute inset-0 bg-white/20 animate-pulse rounded-t-2xl" />}
