                       <div className={`px-5 py-2 rounded-2xl text-[11px] font-black border-2 shadow-lg ${
                         report.directive.includes('BUY') ? 'bg-green-600/10 border-green-600/20 text-green-400 shadow-green-600/10' :
                         report.directive.includes('SELL') ? 'bg-red-600/10 border-red-600/20 text-red-400 shadow-red-600/10' :
                         'bg-yellow-600/10 border-yellow-600/20 text-yellow-400 shadow-yellow-600/10'
                       }`}>
                         DIRECTIVE: {report.directive.replace('_', ' ')}
                       </div>
                       <div className="text-xs font-black text-white/50 tracking-widest uppercase">{report.confidence_score}% CONF</div>
                    </div>

                    <h3 className="text-5xl font-black text-white uppercase tracking-tighter leading-[0.9] mb-6 drop-shadow-2xl">
                      {report.action_title}
                    </h3>

                    <p className="text-base text-gray-400 leading-relaxed font-medium mb-10 pl-6 border-l-4 border-red-600/50 italic">
                      {report.retail_reasoning}
                    </p>

                    <div className="grid grid-cols-2 gap-4 mb-10">
                       <div className="bg-white/5 p-5 rounded-[24px] border border-white/10 shadow-inner">
                          <span className="text-[10px] text-gray-500 font-black uppercase block mb-1">Entry Range</span>
                          <span className="text-lg font-black text-white mono">${report.entry_price.toFixed(6)}</span>
                       </div>
                       <div className="bg-white/5 p-5 rounded-[24px] border border-white/10 shadow-inner">
                          <span className="text-[10px] text-gray-500 font-black uppercase block mb-1">Target TP</span>
                          <span className="text-lg font-black text-green-400 mono">${report.target_profit.toFixed(6)}</span>
                       </div>
                    </div>
                 </div>
               ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center py-20 opacity-20 z-10">
                    <Rocket size={80} className="mb-8 text-gray-500" />
                    <p className="text-sm font-black uppercase tracking-[0.5em] max-w-[200px] text-gray-400">Scan Required to Unlock Alpha</p>
                 </div>
               )}

               <button 
                onClick={runDeFiScan}
                disabled={!currentToken || isAnalyzing}
                className="w-full py-6 bg-white text-black font-black uppercase tracking-[0.3em] text-[11px] rounded-[24px] hover:bg-red-600 hover:text-white transition-all disabled:opacity-20 shadow-[0_15px_40px_rgba(255,255,255,0.1)] mt-auto active:scale-95 z-10"
               >
                 {currentToken ? `Run ${strategy} Scan` : 'Insert Asset Contract'}
               </button>
            </div>

            {/* PROFIT SIMULATOR */}
            <ProfitSimulator 
              capital={tradingCapital} 
              onCapitalChange={setTradingCapital} 
              confidence={report ? report.confidence_score : 50} 
            />
          </div>
        </div>
      </main>

      {/* ERROR OVERLAY */}
      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-600 text-white px-10 py-5 rounded-[30px] shadow-[0_30px_60px_rgba(220,38,38,0.5)] flex items-center gap-6 z-[200] animate-bounce-slow">
          <Zap size={32} />
