            </div>

            {/* FINANCIAL PROJECTION */}
            <div className="scale-105 origin-top">
              <ProfitSimulator 
                capital={tradingCapital} 
                onCapitalChange={setTradingCapital} 
                confidence={report ? report.energy_rating : 50} 
              />
