      <style>{`
        @keyframes slide {
          from { transform: translateX(-100%); }
          to { transform: translateX(400%); }
        }
        @keyframes bounce-slow {
          0%, 100% { transform: translate(-50%, 0); }
          50% { transform: translate(-50%, -15px); }
