      - MARKET_STRUCTURE: ${context.technicals?.marketStructure}
      - VOL_DELTA: $${context.technicals?.volDelta?.toLocaleString()}
      - OB_IMBALANCE: ${(context.technicals?.obImbalance * 100).toFixed(2)}%
