export const fetchTokenByAddress = async (address: string): Promise<EnhancedTokenData | null> => {
  const isEth = /^0x[a-fA-F0-9]{40}$/.test(address);
  const isSol = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(address);

  if (!isEth && !isSol) return null;

  const platform = isEth ? 'ethereum' : 'solana';

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 3000);

    const contractRes = await fetch(
      `https://api.coingecko.com/api/v3/coins/${platform}/contract/${address}`,
      { signal: controller.signal }
    );

    clearTimeout(timeoutId);

    if (contractRes.ok) {
      const data = await contractRes.json();
      return {
        id: data.id,
        symbol: data.symbol.toUpperCase(),
        name: data.name,
        priceUsd: data.market_data.current_price.usd,
        priceChange24h: data.market_data.price_change_percentage_24h || 0,
        marketCap: data.market_data.market_cap.usd || 0,
        volume24h: data.market_data.total_volume.usd || 0,
        image: data.image.large,
        isSimulated: false
      };
    }
  } catch (err) {}

  return {
    id: `sim-${address}`,
    symbol: isEth ? 'ETH-B' : 'SOL-B',
    name: `Dark Forest Target (${address.slice(0, 6)}...)`,
    priceUsd: 1.25 + Math.random() * 850,
    priceChange24h: (Math.random() - 0.4) * 15,
    marketCap: 1500000 + Math.random() * 8500000,
    volume24h: 300000 + Math.random() * 1200000,
    image: isEth 
      ? "https://assets.coingecko.com/coins/images/279/large/ethereum.png"
      : "https://assets.coingecko.com/coins/images/4128/large/solana.png",
    isSimulated: true
  };
};

export const fetchTopMarkets = async (page: number = 1): Promise<TokenData[]> => {
  try {
    const res = await fetch(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=${page}&sparkline=false`);
    if (res.ok) {
      const data = await res.json();
      return data.map((item: any) => ({
        id: item.id,
        symbol: item.symbol.toUpperCase(),
        name: item.name,
        priceUsd: item.current_price,
        priceChange24h: item.price_change_percentage_24h,
        marketCap: item.market_cap,
        volume24h: item.total_volume,
        image: item.image,
        rank: item.market_cap_rank
      }));
    }
  } catch (e) {
    console.error("Top Market Scan Failed, using fallbacks.");
  }
  return Array.from({ length: 20 }, (_, i) => ({
    id: `mock-${i}`,
    symbol: 'MOCK',
    name: 'Scan Active...',
    priceUsd: 100 + Math.random() * 1000,
    priceChange24h: (Math.random() - 0.5) * 10,
    marketCap: 1e9 - (i * 1e7),
    volume24h: 1e8,
    rank: i + 1
  }));
};

