import React, { useEffect, useRef, useState } from 'react';
import { Share2, Zap, AlertTriangle, Target, Box, Info } from 'lucide-react';
import * as d3 from 'd3';

interface WalletNode extends d3.SimulationNodeDatum {
  id: string;
  type: 'CORE' | 'SNIPER' | 'RETAIL';
  val: number;
}

interface WalletLink extends d3.SimulationLinkDatum<WalletNode> {
  source: string | WalletNode;
  target: string | WalletNode;
}

interface WalletGraphProps {
  data: {
    nodes: WalletNode[];
    links: WalletLink[];
  } | null;
}

const WalletGraph: React.FC<WalletGraphProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [nodes, setNodes] = useState<WalletNode[]>([]);
  const [links, setLinks] = useState<WalletLink[]>([]);
  const [hoveredNode, setHoveredNode] = useState<WalletNode | null>(null);

  useEffect(() => {
    if (!data || !containerRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    // Deep copy data to avoid mutating original objects during simulation
    const simulationNodes: WalletNode[] = data.nodes.map(d => ({ ...d }));
    const simulationLinks: WalletLink[] = data.links.map(d => ({ ...d }));

    const simulation = d3.forceSimulation<WalletNode>(simulationNodes)
      .force("link", d3.forceLink<WalletNode, WalletLink>(simulationLinks).id(d => d.id).distance(120))
      .force("charge", d3.forceManyBody().strength(-400))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => (d as WalletNode).val * 1.5));

    simulation.on("tick", () => {
      setNodes([...simulationNodes]);
      setLinks([...simulationLinks]);
    });

    return () => simulation.stop();
  }, [data]);

  if (!data) return (
    <div className="h-full flex flex-col items-center justify-center opacity-20 text-center p-12 bg-[#0a0a0a] rounded-[32px] border border-white/5">
      <Share2 size={48} className="mb-4 text-gray-500" />
      <p className="text-xs font-black uppercase tracking-widest text-gray-500">Scan Required to Initialize Topology</p>
    </div>
  );

  const getNodeColor = (type: string) => {
    switch (type) {
      case 'CORE': return 'bg-red-600 border-red-400 shadow-[0_0_30px_rgba(220,38,38,0.5)]';
      case 'SNIPER': return 'bg-orange-500 border-orange-300 shadow-[0_0_20px_rgba(249,115,22,0.4)]';
      default: return 'bg-gray-800 border-gray-600 shadow-none';
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case 'CORE': return <Target size={24} className="text-white" />;
      case 'SNIPER': return <Zap size={16} className="text-white" />;
      default: return <Box size={14} className="text-gray-400" />;
    }
  };

  return (
    <div className="h-full w-full relative overflow-hidden bg-[#0a0a0a] rounded-[32px] border border-white/5 flex flex-col" ref={containerRef}>
      {/* HUD Overlay */}
      <div className="absolute top-8 left-8 z-30 pointer-events-none">
        <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em] mb-1">Topology: Visual Intelligence</h3>
        <p className="text-[9px] text-red-500 mono font-bold uppercase animate-pulse">Analyzing Transaction Clusters...</p>
      </div>

      <div className="absolute top-8 right-8 z-30 flex gap-4">
        <div className="bg-red-500/10 border border-red-500/20 px-3 py-1.5 rounded-xl flex items-center gap-2">
          <AlertTriangle size={12} className="text-red-500" />
          <span className="text-[9px] font-black text-red-500 uppercase">Integrity: Compromised</span>
        </div>
      </div>

      {/* SVG for Connections */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-10">
        <defs>
          <linearGradient id="linkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="rgba(239, 68, 68, 0.4)" />
            <stop offset="100%" stopColor="rgba(255, 255, 255, 0.05)" />
          </linearGradient>
        </defs>
        {links.map((link, i) => {
          const source = link.source as WalletNode;
          const target = link.target as WalletNode;
          if (!source.x || !target.x) return null;

          return (
            <line
              key={`link-${i}`}
              x1={source.x}
              y1={source.y}
              x2={target.x}
              y2={target.y}
              stroke="url(#linkGradient)"
              strokeWidth="1.5"
              strokeDasharray="4,4"
              className="animate-dash"
            />
          );
        })}
      </svg>

      {/* Node Rendering (HTML for easier Lucide integration) */}
      <div className="absolute inset-0 z-20 pointer-events-none">
        {nodes.map((node) => (
          <div
            key={node.id}
            className={`absolute rounded-full border-2 flex items-center justify-center transition-all duration-300 pointer-events-auto cursor-pointer group ${getNodeColor(node.type)}`}
            style={{
              width: `${node.val * 2}px`,
              height: `${node.val * 2}px`,
              left: `${node.x}px`,
              top: `${node.y}px`,
              transform: 'translate(-50%, -50%)',
            }}
            onMouseEnter={() => setHoveredNode(node)}
            onMouseLeave={() => setHoveredNode(null)}
          >
            {getIcon(node.type)}

            {/* Tooltip */}
            {hoveredNode?.id === node.id && (
              <div className="absolute top-full mt-4 bg-black/90 border border-white/10 p-4 rounded-2xl shadow-2xl backdrop-blur-xl z-50 min-w-[200px] pointer-events-none animate-fade-in">
                <div className="flex items-center gap-3 mb-3 border-b border-white/5 pb-2">
                  <div className={`w-2 h-2 rounded-full ${node.type === 'CORE' ? 'bg-red-500' : node.type === 'SNIPER' ? 'bg-orange-500' : 'bg-gray-500'}`} />
                  <span className="text-[10px] font-black uppercase text-white tracking-widest">{node.type} NODE</span>
                </div>
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span className="text-[9px] text-gray-500 uppercase font-bold">Address</span>
                    <span className="text-[9px] text-white mono">{node.id}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-[9px] text-gray-500 uppercase font-bold">Influence</span>
                    <span className="text-[9px] text-white mono">{node.val.toFixed(0)} QP</span>
                  </div>
                  {node.type === 'SNIPER' && (
                    <div className="mt-2 py-1 px-2 bg-red-500/20 rounded-md">
                      <span className="text-[8px] text-red-400 font-black uppercase italic">Atomic Swap Logic Detected</span>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Legend Footer */}
      <div className="h-14 border-t border-white/5 mt-auto flex items-center justify-between text-[9px] mono text-gray-500 uppercase tracking-widest px-8 bg-black/40 backdrop-blur-md z-30">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-red-600" />
            <span>MEV Controller</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-orange-500" />
            <span>Sniper Cluster</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-gray-700" />
            <span>Retail Node</span>
          </div>
        </div>
        <div className="flex items-center gap-2 text-blue-400">
          <Info size={12} />
          <span>Force-Directed Analysis Active</span>
        </div>
      </div>

      <style>{`
        @keyframes dash {
          to {
            stroke-dashoffset: -20;
          }
        }
        .animate-dash {
          animation: dash 1s linear infinite;
        }
        .animate-fade-in {
          animation: fadeIn 0.2s ease-out forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default WalletGraph;

