import React, { useEffect, useRef, useState } from 'react';
import { Share2, Zap, AlertTriangle, Target, Box, Info, ArrowRightLeft } from 'lucide-react';
import * as d3 from 'd3';

// Explicitly define x and y to ensure they are available on the WalletNode type,
// avoiding TypeScript inheritance issues with d3.SimulationNodeDatum.
interface WalletNode extends d3.SimulationNodeDatum {
  id: string;
  type: 'CORE' | 'SNIPER' | 'RETAIL';
  val: number;
  x?: number;
  y?: number;
}

interface WalletLink extends d3.SimulationLinkDatum<WalletNode> {
  source: string | WalletNode;
  target: string | WalletNode;
  flowValue?: number;
}

interface WalletGraphProps {
  data: {
    nodes: WalletNode[];
    links: WalletLink[];
  } | null;
}

const WalletGraph: React.FC<WalletGraphProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [nodes, setNodes] = useState<WalletNode[]>([]);
  const [links, setLinks] = useState<WalletLink[]>([]);
  const [hoveredNode, setHoveredNode] = useState<WalletNode | null>(null);

  useEffect(() => {
    if (!data || !containerRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    // Deep copy data to avoid mutating original objects during simulation
    const simulationNodes: WalletNode[] = data.nodes.map(d => ({ ...d }));
    const simulationLinks: WalletLink[] = data.links.map(d => ({ ...d }));

    const simulation = d3.forceSimulation<WalletNode>(simulationNodes)
      .force("link", d3.forceLink<WalletNode, WalletLink>(simulationLinks).id(d => d.id).distance(150))
      .force("charge", d3.forceManyBody().strength(-600))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => (d as WalletNode).val * 2));

    simulation.on("tick", () => {
      setNodes([...simulationNodes]);
      setLinks([...simulationLinks]);
    });

    return () => simulation.stop();
  }, [data]);

  if (!data) return (
    <div className="h-full flex flex-col items-center justify-center opacity-20 text-center p-12 bg-[#0a0a0a] rounded-[32px] border border-white/5">
      <Share2 size={48} className="mb-4 text-gray-500" />
      <p className="text-xs font-black uppercase tracking-widest text-gray-500">Scan Required to Initialize Topology</p>
    </div>
  );

  const getNodeColor = (type: string) => {
    switch (type) {
      case 'CORE': return 'bg-blue-600 border-blue-400 shadow-[0_0_30px_rgba(37,99,235,0.5)]';
      case 'SNIPER': return 'bg-red-600 border-red-400 shadow-[0_0_20px_rgba(220,38,38,0.4)]';
      default: return 'bg-gray-800 border-gray-600 shadow-none';
    }
  };

  const getIcon = (type: string) => {
    switch (type) {
      case 'CORE': return <Target size={24} className="text-white" />;
      case 'SNIPER': return <Zap size={16} className="text-white" />;
      default: return <Box size={14} className="text-gray-400" />;
    }
  };

  const isLinkActive = (link: WalletLink) => {
    if (!hoveredNode) return true;
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;
    return sourceId === hoveredNode.id || targetId === hoveredNode.id;
  };

  const isNodeDimmed = (node: WalletNode) => {
    if (!hoveredNode) return false;
    if (node.id === hoveredNode.id) return false;
    return !links.some(link => {
      const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
      const targetId = typeof link.target === 'string' ? link.target : link.target.id;
      return (sourceId === hoveredNode.id && targetId === node.id) || 
             (targetId === hoveredNode.id && sourceId === node.id);
    });
  };

  return (
    <div className="h-full w-full relative overflow-hidden bg-[#0a0a0a] rounded-[32px] border border-white/5 flex flex-col" ref={containerRef}>
      {/* HUD Overlay */}
      <div className="absolute top-8 left-8 z-30 pointer-events-none">
        <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em] mb-1">Topology: Liquidity Flow Matrix</h3>
        <p className="text-[9px] text-blue-500 mono font-bold uppercase animate-pulse">Tracing Currency Pathways...</p>
      </div>

      <div className="absolute top-8 right-8 z-30 flex gap-4">
        <div className="bg-blue-500/10 border border-blue-500/20 px-3 py-1.5 rounded-xl flex items-center gap-2">
          <ArrowRightLeft size={12} className="text-blue-500" />
          <span className="text-[9px] font-black text-blue-500 uppercase">Cross-Pool Flow Active</span>
        </div>
      </div>

      {/* SVG for Connections and Particles */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none z-10">
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="25" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="rgba(255,255,255,0.1)" />
          </marker>
          <linearGradient id="linkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="rgba(37, 99, 235, 0.4)" />
            <stop offset="100%" stopColor="rgba(255, 255, 255, 0.05)" />
          </linearGradient>
          <linearGradient id="activeLinkGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="rgba(37, 99, 235, 0.8)" />
            <stop offset="100%" stopColor="rgba(37, 99, 235, 0.2)" />
          </linearGradient>
        </defs>
        {links.map((link, i) => {
          const source = link.source as WalletNode;
          const target = link.target as WalletNode;
          if (source.x === undefined || source.y === undefined || target.x === undefined || target.y === undefined) return null;

          const active = isLinkActive(link);
          const dimmed = hoveredNode && !active;

          return (
            <g key={`link-group-${i}`} className={`transition-opacity duration-300 ${dimmed ? 'opacity-10' : 'opacity-100'}`}>
              <line
                x1={source.x}
                y1={source.y}
                x2={target.x}
                y2={target.y}
                stroke={active ? "url(#activeLinkGradient)" : "url(#linkGradient)"}
                strokeWidth={active && hoveredNode ? "2.5" : "1"}
                marker-end="url(#arrowhead)"
              />
              {/* Flow Particles */}
              <circle r="2" fill="#3b82f6" className="animate-flow">
                <animateMotion
                  dur={`${1.5 + Math.random() * 2}s`}
                  repeatCount="indefinite"
                  path={`M ${source.x},${source.y} L ${target.x},${target.y}`}
                />
              </circle>
            </g>
          );
        })}
      </svg>

      {/* Node Rendering */}
      <div className="absolute inset-0 z-20 pointer-events-none">
        {nodes.map((node) => {
          const isHovered = hoveredNode?.id === node.id;
          const dimmed = isNodeDimmed(node);

          return (
            <div
              key={node.id}
              className={`absolute rounded-full border-2 flex items-center justify-center transition-all duration-300 pointer-events-auto cursor-pointer group ${getNodeColor(node.type)}`}
              style={{
                width: `${node.val * 2}px`,
                height: `${node.val * 2}px`,
                left: `${node.x ?? 0}px`,
                top: `${node.y ?? 0}px`,
                transform: `translate(-50%, -50%) ${isHovered ? 'scale(1.2)' : 'scale(1)'}`,
                opacity: dimmed ? 0.2 : 1,
                zIndex: isHovered ? 50 : 20,
              }}
              onMouseEnter={() => setHoveredNode(node)}
              onMouseLeave={() => setHoveredNode(null)}
            >
              {getIcon(node.type)}

              {/* Tooltip */}
              {isHovered && (
                <div className="absolute top-full mt-4 bg-black/90 border border-white/10 p-4 rounded-2xl shadow-2xl backdrop-blur-xl z-50 min-w-[200px] pointer-events-none animate-fade-in">
                  <div className="flex items-center gap-3 mb-3 border-b border-white/5 pb-2">
                    <div className={`w-2 h-2 rounded-full ${node.type === 'CORE' ? 'bg-blue-500' : node.type === 'SNIPER' ? 'bg-red-500' : 'bg-gray-500'}`} />
                    <span className="text-[10px] font-black uppercase text-white tracking-widest">{node.type} BUBBLE</span>
                  </div>
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-[9px] text-gray-500 uppercase font-bold">Address</span>
                      <span className="text-[9px] text-white mono">{node.id}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[9px] text-gray-500 uppercase font-bold">Flow Vol</span>
                      <span className="text-[9px] text-white mono">{node.val.toFixed(0)} ETH</span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Legend Footer */}
      <div className="h-14 border-t border-white/5 mt-auto flex items-center justify-between text-[9px] mono text-gray-500 uppercase tracking-widest px-8 bg-black/40 backdrop-blur-md z-30">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-blue-600 shadow-[0_0_10px_rgba(37,99,235,0.5)]" />
            <span>Liquidity Pool</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.5)]" />
            <span>High-Flow Bot</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-gray-700" />
            <span>Passive Node</span>
          </div>
        </div>
        <div className="flex items-center gap-2 text-blue-400">
          <Info size={12} />
          <span>Bubble Topology: Particle Flow Representation</span>
        </div>
      </div>

      <style>{`
        .animate-fade-in {
          animation: fadeIn 0.2s ease-out forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-flow {
          filter: drop-shadow(0 0 4px #3b82f6);
        }
      `}</style>
    </div>
  );
};

