export const generateWalletGraph = () => {
  const nodes = [
    { id: 'Pool-Alpha', group: 1, val: 60, type: 'CORE' },
    { id: 'Pool-Beta', group: 1, val: 55, type: 'CORE' }
  ];
  const links = [];

  // Connect Pools
  links.push({ source: 'Pool-Alpha', target: 'Pool-Beta', flowValue: 100 });

  // Add surrounding nodes
  for (let i = 0; i < 15; i++) {
