    const type = isSniper ? 'SNIPER' : 'RETAIL';
    const val = isSniper ? 20 + Math.random() * 10 : 10 + Math.random() * 5;
    nodes.push({ id: `Wallet-${i}`, group: 2, val, type });

    // Randomly connect to one of the pools
    const targetPool = Math.random() > 0.5 ? 'Pool-Alpha' : 'Pool-Beta';

    // Create directional flows
    if (Math.random() > 0.5) {
      links.push({ source: `Wallet-${i}`, target: targetPool, flowValue: val });
