export const calculateGAF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = (max - min) || 1;
  const scaled = data.map(x => (2 * (x - min) / range) - 1);
  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    matrix[i] = [];
    for (let j = 0; j < n; j++) {
      const xi = Math.max(-1, Math.min(1, scaled[i]));
      const xj = Math.max(-1, Math.min(1, scaled[j]));
      const val = xi * xj - Math.sqrt(1 - xi ** 2) * Math.sqrt(1 - xj ** 2);
      matrix[i][j] = val;
    }
  }
  return matrix;
};

export const calculateMTF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  const numBins = 10;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = (max - min) || 1;
  const bins = data.map(x => {
    const b = Math.floor(((x - min) / range) * numBins);
    return Math.min(b, numBins - 1);
  });
  const transitionMatrix = Array.from({ length: numBins }, () => new Array(numBins).fill(0));
  for (let i = 0; i < n - 1; i++) {
    transitionMatrix[bins[i]][bins[i + 1]]++;
  }
  for (let i = 0; i < numBins; i++) {
    const sum = transitionMatrix[i].reduce((a, b) => a + b, 0);
    if (sum > 0) {
      for (let j = 0; j < numBins; j++) {
        transitionMatrix[i][j] /= sum;
      }
    }
  }
  const mtf: number[][] = [];
  for (let i = 0; i < n; i++) {
    mtf[i] = [];
    for (let j = 0; j < n; j++) {
      mtf[i][j] = transitionMatrix[bins[i]][bins[j]];
    }
  }
  return mtf;
};

/**
 * Generates synthetic technical analysis data with volume delta and orderbook imbalance
 */
export const generateTechnicalData = (price: number): any => {
  const rsi = 30 + Math.random() * 40;
  const ema20 = price * (1 + (Math.random() - 0.5) * 0.02);
  const ema50 = price * (1 + (Math.random() - 0.5) * 0.05);

  // Simulated Volume Delta (Buy Vol - Sell Vol)
  const volDelta = (Math.random() - 0.45) * 1000000; 
  const obImbalance = (Math.random() - 0.4) * 0.5; 

  const structures: ('BULLISH' | 'BEARISH' | 'RANGING')[] = ['BULLISH', 'BEARISH', 'RANGING'];
  const marketStructure = structures[Math.floor(Math.random() * structures.length)];

  return {
    rsi,
    ema20,
    ema50,
    volatility: 0.05 + Math.random() * 0.15,
    marketStructure,
    volDelta,
    obImbalance,
    oracleVerified: Math.random() > 0.1 
  };
};

export const generateMempoolData = (baseGas: number): any[] => {
  const txs = [];
  const now = Date.now();
  for (let i = 0; i < 50; i++) {
    const isSandwich = i > 40;
    txs.push({
      id: `tx-${i}`,
      gasPrice: baseGas + (isSandwich ? 50 + Math.random() * 20 : Math.random() * 30),
      value: Math.random() * 5,
      time: now - (i * 100),
      type: isSandwich ? 'swap' : 'transfer',
      isMEV: isSandwich
    });
  }
  return txs;
};

export const generateTopographyData = (midPrice: number): any[] => {
  const ticks = [];
  for (let i = -20; i < 20; i++) {
    const price = midPrice * (1 + (i * 0.001));
    const isPeak = Math.abs(i) === 5 || Math.abs(i) === 15;
    ticks.push({
      price,
      depth: isPeak ? 80 + Math.random() * 20 : 10 + Math.random() * 30,
      isPeak
    });
  }
  return ticks;
};

/**
 * Generates token-specific wallet interaction graph data
 */
export const generateWalletGraph = (symbol: string = 'ETH', mode: 'INSTITUTIONAL' | 'RETAIL' = 'INSTITUTIONAL') => {
  const isInst = mode === 'INSTITUTIONAL';

  const nodes = [
    { id: `Binance-${symbol}`, group: 3, val: 80, type: 'CORE', label: 'Binance CEX' },
    { id: `Bybit-${symbol}`, group: 3, val: 75, type: 'CORE', label: 'Bybit CEX' },
    { id: `DEX-Pool-${symbol}`, group: 1, val: 65, type: 'CORE', label: `${symbol}/USDC Pool` },
  ];

  const links = [];

  // Core exchange-to-pool bridges
  links.push({ source: `Binance-${symbol}`, target: `DEX-Pool-${symbol}`, flowValue: 500 });
  links.push({ source: `Bybit-${symbol}`, target: `DEX-Pool-${symbol}`, flowValue: 400 });

  // Add surrounding nodes based on mode
  const count = isInst ? 12 : 25;
  for (let i = 0; i < count; i++) {
    const isWhale = isInst && Math.random() > 0.7;
    const type = isWhale ? 'SNIPER' : 'RETAIL';
    const val = isWhale ? 40 + Math.random() * 20 : 10 + Math.random() * 8;
    nodes.push({ id: `Wallet-${symbol}-${i}`, group: 2, val, type, label: `Wallet ${i}` });

    // Connect to logic
    const targets = [`Binance-${symbol}`, `Bybit-${symbol}`, `DEX-Pool-${symbol}`];
    const target = targets[Math.floor(Math.random() * targets.length)];

    if (Math.random() > 0.5) {
      links.push({ source: `Wallet-${symbol}-${i}`, target: target, flowValue: val });
    } else {
      links.push({ source: target, target: `Wallet-${symbol}-${i}`, flowValue: val });
    }
  }

  return { nodes, links };
};

export const generateMetricChartData = (base: number, points: number = 20) => {
  const data = [];
  let current = base;
  for (let i = 0; i < points; i++) {
    current = current * (1 + (Math.random() - 0.48) * 0.05);
    data.push(current);
  }
  return data;
};

export const calculateGAF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = (max - min) || 1;
  const scaled = data.map(x => (2 * (x - min) / range) - 1);
  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    matrix[i] = [];
    for (let j = 0; j < n; j++) {
      const xi = Math.max(-1, Math.min(1, scaled[i]));
      const xj = Math.max(-1, Math.min(1, scaled[j]));
      const val = xi * xj - Math.sqrt(1 - xi ** 2) * Math.sqrt(1 - xj ** 2);
      matrix[i][j] = val;
    }
  }
  return matrix;
};

export const calculateMTF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  const numBins = 10;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = (max - min) || 1;
  const bins = data.map(x => {
    const b = Math.floor(((x - min) / range) * numBins);
    return Math.min(b, numBins - 1);
  });
  const transitionMatrix = Array.from({ length: numBins }, () => new Array(numBins).fill(0));
  for (let i = 0; i < n - 1; i++) {
    transitionMatrix[bins[i]][bins[i + 1]]++;
  }
  for (let i = 0; i < numBins; i++) {
    const sum = transitionMatrix[i].reduce((a, b) => a + b, 0);
    if (sum > 0) {
      for (let j = 0; j < numBins; j++) {
        transitionMatrix[i][j] /= sum;
      }
    }
  }
  const mtf: number[][] = [];
  for (let i = 0; i < n; i++) {
    mtf[i] = [];
    for (let j = 0; j < n; j++) {
      mtf[i][j] = transitionMatrix[bins[i]][bins[j]];
    }
  }
  return mtf;
};

import React, { useEffect, useRef, useState } from 'react';
import { Share2, Zap, AlertTriangle, Target, Box, Info, ArrowRightLeft, MousePointer2 } from 'lucide-react';
import * as d3 from 'd3';

interface WalletNode extends d3.SimulationNodeDatum {
  id: string;
  type: 'CORE' | 'SNIPER' | 'RETAIL';
  val: number;
  label?: string;
  x?: number;
  y?: number;
}

interface WalletLink extends d3.SimulationLinkDatum<WalletNode> {
  source: string | WalletNode;
  target: string | WalletNode;
  flowValue?: number;
}

interface WalletGraphProps {
  data: {
    nodes: WalletNode[];
    links: WalletLink[];
  } | null;
}

const WalletGraph: React.FC<WalletGraphProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const [nodes, setNodes] = useState<WalletNode[]>([]);
  const [links, setLinks] = useState<WalletLink[]>([]);
  const [hoveredNode, setHoveredNode] = useState<WalletNode | null>(null);
  const [transform, setTransform] = useState({ x: 0, y: 0, k: 1 });

  useEffect(() => {
    if (!data || !containerRef.current || !svgRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    const simulationNodes: WalletNode[] = data.nodes.map(d => ({ ...d }));
    const simulationLinks: WalletLink[] = data.links.map(d => ({ ...d }));

    const simulation = d3.forceSimulation<WalletNode>(simulationNodes)
      .force("link", d3.forceLink<WalletNode, WalletLink>(simulationLinks).id(d => d.id).distance(180))
      .force("charge", d3.forceManyBody().strength(-800))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => (d as WalletNode).val * 2.5));

    // Handle Zoom
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.2, 5])
      .on("zoom", (event) => {
        setTransform(event.transform);
      });

    d3.select(svgRef.current).call(zoom);

    simulation.on("tick", () => {
      setNodes([...simulationNodes]);
      setLinks([...simulationLinks]);
    });

    return () => simulation.stop();
  }, [data]);

  if (!data) return (
    <div className="h-full flex flex-col items-center justify-center opacity-20 text-center p-12 bg-[#0a0a0a] rounded-[32px] border border-white/5">
      <Share2 size={48} className="mb-4 text-gray-500" />
      <p className="text-xs font-black uppercase tracking-widest text-gray-500">Scan Required to Initialize Topology</p>
    </div>
  );

  const getNodeColor = (type: string, id: string) => {
    if (id.includes('Binance')) return 'bg-yellow-500 border-yellow-300 shadow-[0_0_30px_rgba(234,179,8,0.5)]';
    if (id.includes('Bybit')) return 'bg-orange-600 border-orange-400 shadow-[0_0_30px_rgba(234,88,12,0.5)]';
    switch (type) {
      case 'CORE': return 'bg-blue-600 border-blue-400 shadow-[0_0_30px_rgba(37,99,235,0.5)]';
      case 'SNIPER': return 'bg-red-600 border-red-400 shadow-[0_0_20px_rgba(220,38,38,0.4)]';
      default: return 'bg-gray-800 border-gray-600 shadow-none';
    }
  };

  const isLinkActive = (link: WalletLink) => {
    if (!hoveredNode) return true;
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;
    return sourceId === hoveredNode.id || targetId === hoveredNode.id;
  };

  const isNodeDimmed = (node: WalletNode) => {
    if (!hoveredNode) return false;
    if (node.id === hoveredNode.id) return false;
    return !links.some(link => {
      const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
      const targetId = typeof link.target === 'string' ? link.target : link.target.id;
      return (sourceId === hoveredNode.id && targetId === node.id) || 
             (targetId === hoveredNode.id && sourceId === node.id);
    });
  };

  return (
    <div className="h-full w-full relative overflow-hidden bg-[#060606] rounded-[32px] border border-white/5 flex flex-col" ref={containerRef}>
      {/* Interaction HUD */}
      <div className="absolute top-8 left-8 z-30 pointer-events-none flex flex-col gap-1">
        <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Cross-Border Analytics</h3>
        <p className="text-[9px] text-blue-500 mono font-bold uppercase flex items-center gap-2">
          <MousePointer2 size={10} /> Drag nodes to inspect clusters | Scroll to Zoom
        </p>
      </div>

      <div className="absolute top-8 right-8 z-30 flex gap-4">
        <div className="bg-white/5 backdrop-blur-md border border-white/10 px-4 py-2 rounded-2xl flex items-center gap-3">
          <div className="flex -space-x-2">
            <div className="w-5 h-5 rounded-full bg-yellow-500 border border-black flex items-center justify-center text-[7px] font-bold">BN</div>
            <div className="w-5 h-5 rounded-full bg-orange-600 border border-black flex items-center justify-center text-[7px] font-bold">BY</div>
          </div>
          <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Global CEX Bridging Active</span>
        </div>
      </div>

      {/* Main SVG Content */}
      <svg 
        ref={svgRef} 
        className="absolute inset-0 w-full h-full cursor-grab active:cursor-grabbing z-10"
      >
        <g transform={`translate(${transform.x}, ${transform.y}) scale(${transform.k})`}>
          <defs>
            <marker id="arrow" markerWidth="10" markerHeight="10" refX="25" refY="3" orient="auto">
              <path d="M0,0 L0,6 L9,3 z" fill="rgba(255,255,255,0.1)" />
            </marker>
            <linearGradient id="linkGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="rgba(59, 130, 246, 0.4)" />
              <stop offset="100%" stopColor="rgba(30, 64, 175, 0.1)" />
            </linearGradient>
          </defs>

          {/* Links */}
          {links.map((link, i) => {
            const s = link.source as WalletNode;
            const t = link.target as WalletNode;
            if (s.x === undefined || t.x === undefined) return null;
            const active = isLinkActive(link);
            const dimmed = hoveredNode && !active;

            return (
              <g key={`link-wrap-${i}`} className={`transition-opacity duration-300 ${dimmed ? 'opacity-10' : 'opacity-100'}`}>
                <line
                  x1={s.x} y1={s.y} x2={t.x} y2={t.y}
                  stroke="url(#linkGrad)"
                  strokeWidth={active && hoveredNode ? "3" : "1.5"}
                  marker-end="url(#arrow)"
                />
                <circle r="2.5" fill="#60a5fa" className="animate-flow-glow">
                  <animateMotion
                    dur={`${1 + Math.random() * 2}s`}
                    repeatCount="indefinite"
                    path={`M ${s.x},${s.y} L ${t.x},${t.y}`}
                  />
                </circle>
              </g>
            );
          })}

          {/* Nodes (rendered as ForeignObjects for HTML content) */}
          {nodes.map((node) => {
            const isHovered = hoveredNode?.id === node.id;
            const dimmed = isNodeDimmed(node);
            const size = node.val * 2;

            return (
              <foreignObject
                key={node.id}
                x={(node.x ?? 0) - size / 2}
                y={(node.y ?? 0) - size / 2}
                width={size}
                height={size}
                className="overflow-visible pointer-events-auto"
              >
                <div
                  className={`w-full h-full rounded-full border-2 flex items-center justify-center transition-all duration-300 cursor-pointer ${getNodeColor(node.type, node.id)}`}
                  style={{
                    transform: isHovered ? 'scale(1.25)' : 'scale(1)',
                    opacity: dimmed ? 0.2 : 1,
                  }}
                  onMouseEnter={() => setHoveredNode(node)}
                  onMouseLeave={() => setHoveredNode(null)}
                >
                  {node.id.includes('Binance') ? <span className="text-[10px] font-black text-black">BN</span> :
                   node.id.includes('Bybit') ? <span className="text-[10px] font-black text-white">BB</span> :
                   node.type === 'CORE' ? <Target size={size/2.5} className="text-white" /> :
                   node.type === 'SNIPER' ? <Zap size={size/2.5} className="text-white" /> :
                   <Box size={size/2.5} className="text-gray-400" />}
                </div>

                {/* Node Labels */}
                <div className={`absolute top-full left-1/2 -translate-x-1/2 mt-1 whitespace-nowrap pointer-events-none transition-opacity ${isHovered ? 'opacity-100' : 'opacity-40'}`}>
                  <span className="text-[8px] mono font-bold text-gray-400 uppercase tracking-tighter">
                    {node.label || node.id.split('-')[0]}
                  </span>
                </div>

                {/* Tooltip Overlay */}
                {isHovered && (
                  <div className="absolute top-1/2 left-full ml-4 -translate-y-1/2 bg-black/95 border border-white/10 p-4 rounded-2xl shadow-2xl backdrop-blur-xl z-50 min-w-[180px] pointer-events-none animate-fade-in">
                    <div className="flex items-center gap-2 mb-2">
                       <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                       <span className="text-[9px] font-black text-white uppercase tracking-widest">{node.id.includes('CEX') ? 'EXCHANGE HUB' : 'WALLET NODE'}</span>
                    </div>
                    <div className="space-y-1 text-[10px]">
                      <div className="flex justify-between"><span className="text-gray-500">ADDR:</span> <span className="mono text-white">{node.id.slice(0, 10)}...</span></div>
                      <div className="flex justify-between"><span className="text-gray-500">FLOW:</span> <span className="mono text-green-400">+{node.val.toFixed(2)} Vol</span></div>
                    </div>
                  </div>
                )}
              </foreignObject>
            );
          })}
        </g>
      </svg>

      {/* Interactive Legend */}
      <div className="h-14 border-t border-white/5 mt-auto flex items-center justify-between text-[9px] mono text-gray-500 uppercase tracking-widest px-8 bg-black/40 backdrop-blur-md z-30">
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-yellow-500" />
            <span>Binance Hub</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-blue-600" />
            <span>Local LP Pool</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-red-600" />
            <span>Atomic Sniper</span>
          </div>
        </div>
        <div className="flex items-center gap-2 text-green-500">
          <Info size={12} />
          <span>Real-Time Bubble Topology Engine Active</span>
        </div>
      </div>

      <style>{`
        .animate-flow-glow {
          filter: drop-shadow(0 0 5px #3b82f6);
        }
        .animate-fade-in {
          animation: fadeIn 0.15s ease-out forwards;
        }
        @keyframes fadeIn {
          from { opacity: 0; transform: translate(10px, -50%); }
          to { opacity: 1; transform: translate(0, -50%); }
        }
      `}</style>
    </div>
  );
};

