  const ticks = [];
  for (let i = -20; i < 20; i++) {
    const price = midPrice * (1 + (i * 0.001));
    const isPeak = Math.abs(i) === 5 || Math.abs(i) === 15;
    ticks.push({
      price,
      depth: isPeak ? 80 + Math.random() * 20 : 10 + Math.random() * 30,
      isPeak
    });
  }
  return ticks;
};

/**
 * Generates token-specific global market topology
 * Includes multiple CEX (Binance, Coinbase, OKX) and DEX (Uniswap, Sushi) venues
 */
export const generateWalletGraph = (symbol: string = 'ETH', mode: 'INSTITUTIONAL' | 'RETAIL' = 'INSTITUTIONAL') => {
  const isInst = mode === 'INSTITUTIONAL';

  const nodes = [
    // CEX HUBS
    { id: `Binance-${symbol}`, group: 3, val: 85, type: 'CORE', label: 'Binance (CEX)' },
    { id: `Coinbase-${symbol}`, group: 3, val: 70, type: 'CORE', label: 'Coinbase (CEX)' },
    { id: `OKX-${symbol}`, group: 3, val: 65, type: 'CORE', label: 'OKX (CEX)' },
    { id: `Bybit-${symbol}`, group: 3, val: 60, type: 'CORE', label: 'Bybit (CEX)' },

    // DEX HUBS
    { id: `Uniswap-V3-${symbol}`, group: 1, val: 75, type: 'CORE', label: `UniV3 ${symbol}/USDC` },
    { id: `SushiSwap-${symbol}`, group: 1, val: 50, type: 'CORE', label: `Sushi ${symbol}/ETH` },
  ];

  const links = [];

  // 1. Cross-Market Arbitrage Links (CEX <-> CEX)
  links.push({ source: `Binance-${symbol}`, target: `Coinbase-${symbol}`, flowValue: 1000 });
  links.push({ source: `OKX-${symbol}`, target: `Bybit-${symbol}`, flowValue: 800 });

  // 2. Bridge Links (CEX <-> DEX)
  links.push({ source: `Binance-${symbol}`, target: `Uniswap-V3-${symbol}`, flowValue: 1200 });
  links.push({ source: `Coinbase-${symbol}`, target: `Uniswap-V3-${symbol}`, flowValue: 600 });
  links.push({ source: `OKX-${symbol}`, target: `SushiSwap-${symbol}`, flowValue: 400 });

  // 3. User Wallet Population
  const walletCount = isInst ? 15 : 30;
  for (let i = 0; i < walletCount; i++) {
    const isWhale = isInst && Math.random() > 0.6;
    const type = isWhale ? 'SNIPER' : 'RETAIL';
    const val = isWhale ? 45 + Math.random() * 25 : 8 + Math.random() * 10;
    const id = `Wallet-${symbol}-${i}`;

    nodes.push({ id, group: 2, val, type, label: isWhale ? `Whale ${i}` : `Trader ${i}` });

    // Connect to a primary market venue
    const venues = [`Binance-${symbol}`, `Coinbase-${symbol}`, `Uniswap-V3-${symbol}`, `OKX-${symbol}`];
    const primaryVenue = venues[Math.floor(Math.random() * venues.length)];

    if (Math.random() > 0.4) {
      links.push({ source: id, target: primaryVenue, flowValue: val });
    } else {
      links.push({ source: primaryVenue, target: id, flowValue: val });
    }

    // Secondary connection for slippage/arbitrage traders
    if (isWhale || Math.random() > 0.8) {
        const secondaryVenue = venues[Math.floor(Math.random() * venues.length)];
        if (secondaryVenue !== primaryVenue) {
            links.push({ source: id, target: secondaryVenue, flowValue: val * 0.3 });
        }
    }
  }

  return { nodes, links };
};

