 */
export const generateWalletGraph = (symbol: string = 'ETH', mode: 'INSTITUTIONAL' | 'RETAIL' = 'INSTITUTIONAL') => {
  const isInst = mode === 'INSTITUTIONAL';

  // VENUES: The Endpoints of the trade
  const nodes = [
    // THE NQ SWAP INSTITUTIONAL HUB (The Router)
    { id: `NQ-SWAP-SOR`, group: 5, val: 100, type: 'CORE', label: 'NQ Swap: Smart Order Router' },

    // CEX HUBS
    { id: `Binance-${symbol}`, group: 3, val: 65, type: 'CORE', label: 'Binance (CEX)' },
    { id: `Coinbase-${symbol}`, group: 3, val: 60, type: 'CORE', label: 'Coinbase (CEX)' },
    { id: `OKX-${symbol}`, group: 3, val: 55, type: 'CORE', label: 'OKX (CEX)' },

    // DEX HUBS
    { id: `Uniswap-V3-${symbol}`, group: 1, val: 70, type: 'CORE', label: `UniV3 ${symbol}/USDC` },
    { id: `SushiSwap-${symbol}`, group: 1, val: 45, type: 'CORE', label: `Sushi ${symbol}/ETH` },
  ];

  const links = [];

  // NQ SWAP AGGREGATION LINKS (NQ Swap <-> Market Venues)
  const venues = [`Binance-${symbol}`, `Coinbase-${symbol}`, `OKX-${symbol}`, `Uniswap-V3-${symbol}`, `SushiSwap-${symbol}`];

  venues.forEach(venue => {
    // Flows represent NQ Swap finding the best price across these markets
    links.push({ 
      source: `NQ-SWAP-SOR`, 
      target: venue, 
      flowValue: 1500,
      isRouting: true // Custom flag for visual distinction
    });
  });

  // PRIVATE WALLET POPULATION (Incoming User Traffic)
  const walletCount = isInst ? 15 : 25;
  for (let i = 0; i < walletCount; i++) {
    const isWhale = isInst && Math.random() > 0.6;
    const type = isWhale ? 'SNIPER' : 'RETAIL';
    const val = isWhale ? 40 + Math.random() * 20 : 10 + Math.random() * 5;
    const id = `Wallet-${symbol}-${i}`;

    nodes.push({ id, group: 2, val, type, label: isWhale ? `Whale ${i}` : `Private Wallet ${i}` });

    // NATIVE FLOW: Private Wallets go DIRECTLY to NQ Swap to avoid MEV
    // They do not go to CEX/DEX directly in this partnership model
    links.push({ 
      source: id, 
      target: `NQ-SWAP-SOR`, 
      flowValue: val,
      isProtected: true 
    });
  }

  return { nodes, links };
};

