import React, { useEffect, useRef, useState } from 'react';
import { Share2, Zap, AlertTriangle, Target, Box, Info, ArrowRightLeft, MousePointer2, Globe, Shield, RefreshCw, Layers } from 'lucide-react';
import * as d3 from 'd3';

interface WalletNode extends d3.SimulationNodeDatum {
  id: string;
  type: 'CORE' | 'SNIPER' | 'RETAIL';
  val: number;
  label?: string;
  noteType?: string;
  x?: number;
  y?: number;
}

interface WalletLink extends d3.SimulationLinkDatum<WalletNode> {
  source: string | WalletNode;
  target: string | WalletNode;
  flowValue?: number;
  isRouting?: boolean;
  isProtected?: boolean;
}

interface WalletGraphProps {
  data: {
    nodes: WalletNode[];
    links: WalletLink[];
  } | null;
}

const WalletGraph: React.FC<WalletGraphProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const [nodes, setNodes] = useState<WalletNode[]>([]);
  const [links, setLinks] = useState<WalletLink[]>([]);
  const [hoveredNode, setHoveredNode] = useState<WalletNode | null>(null);
  const [transform, setTransform] = useState({ x: 0, y: 0, k: 0.75 });

  useEffect(() => {
    if (!data || !containerRef.current || !svgRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    const simulationNodes: WalletNode[] = data.nodes.map(d => ({ 
      ...d, 
      noteType: d.id.includes('NQ') ? 'Institutional House' : d.type === 'SNIPER' ? 'Atomic Arbitrageur' : d.id.includes('CEX') ? 'Market Aggregator' : 'Latent Wallet' 
    }));
    const simulationLinks: WalletLink[] = data.links.map(d => ({ ...d }));

    const simulation = d3.forceSimulation<WalletNode>(simulationNodes)
      .force("link", d3.forceLink<WalletNode, WalletLink>(simulationLinks).id(d => d.id).distance(240))
      .force("charge", d3.forceManyBody().strength(-1500))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => (d as WalletNode).id.includes('NQ-SWAP') ? 80 : (d as WalletNode).val * 3.5));

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on("zoom", (event) => setTransform(event.transform));

    d3.select(svgRef.current).call(zoom);

    simulation.on("tick", () => {
      setNodes([...simulationNodes]);
      setLinks([...simulationLinks]);
    });

    return () => simulation.stop();
  }, [data]);

  if (!data) return (
    <div className="h-full flex flex-col items-center justify-center opacity-20 text-center p-12 bg-[#0a0a0a] rounded-[32px] border border-white/5">
      <Share2 size={48} className="mb-4 text-gray-500" />
      <p className="text-xs font-black uppercase tracking-widest text-gray-500">Scan Required to Initialize Topology</p>
    </div>
  );

  const getNodeStyles = (node: WalletNode) => {
    const id = node.id;
    if (id.includes('NQ-SWAP')) return 'bg-gradient-to-br from-indigo-600 to-blue-900 border-blue-400 shadow-[0_0_60px_rgba(79,70,229,0.6)] ring-4 ring-blue-500/20';
    if (id.includes('Binance')) return 'bg-yellow-500 border-yellow-300 shadow-[0_0_40px_rgba(234,179,8,0.3)]';
    if (id.includes('Coinbase')) return 'bg-blue-500 border-blue-300 shadow-[0_0_40px_rgba(59,130,246,0.3)]';
    if (id.includes('Uni') || id.includes('Sushi')) return 'bg-pink-600 border-pink-400 shadow-[0_0_35px_rgba(219,39,119,0.3)]';

    switch (node.type) {
      case 'CORE': return 'bg-gray-800 border-gray-600 shadow-none';
      case 'SNIPER': return 'bg-red-600 border-red-400 shadow-[0_0_20px_rgba(220,38,38,0.4)]';
      default: return 'bg-gray-900 border-white/10 shadow-none';
    }
  };

  const isLinkActive = (link: WalletLink) => {
    if (!hoveredNode) return true;
    const sourceId = typeof link.source === 'string' ? link.source : link.source.id;
    const targetId = typeof link.target === 'string' ? link.target : link.target.id;
    return sourceId === hoveredNode.id || targetId === hoveredNode.id;
  };

  return (
    <div className="h-full w-full relative overflow-hidden bg-[#030303] rounded-[32px] border border-white/5 flex flex-col" ref={containerRef}>

      {/* SOR Header Overlay */}
      <div className="absolute top-8 left-10 z-30 pointer-events-none">
        <div className="flex items-center gap-4 mb-2">
            <div className="p-2 bg-indigo-600 rounded-xl shadow-lg">
                <Shield size={20} className="text-white animate-pulse" />
            </div>
            <div>
                <h3 className="text-[13px] font-black text-white uppercase tracking-[0.4em]">NQ Swap Intelligence</h3>
                <p className="text-[10px] text-indigo-400 mono font-black uppercase">Institutional Anti-MEV Routing ACTIVE</p>
            </div>
        </div>
      </div>

      {/* Dynamic Legend Left */}
      <div className="absolute left-10 bottom-24 z-30 flex flex-col gap-2 p-4 bg-black/60 backdrop-blur-xl border border-white/5 rounded-[24px]">
        <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2 px-1">Node Hierarchy</h4>
        <div className="flex items-center gap-3 px-2">
           <div className="w-2 h-2 rounded bg-indigo-500" />
           <span className="text-[8px] mono text-gray-500 uppercase">NQ SOR House</span>
        </div>
        <div className="flex items-center gap-3 px-2">
           <div className="w-2 h-2 rounded bg-yellow-500" />
           <span className="text-[8px] mono text-gray-500 uppercase">CEX Liquidity Hub</span>
        </div>
        <div className="flex items-center gap-3 px-2">
           <div className="w-2 h-2 rounded bg-pink-500" />
           <span className="text-[8px] mono text-gray-500 uppercase">DEX LP Pool</span>
        </div>
        <div className="flex items-center gap-3 px-2">
           <div className="w-2 h-2 rounded bg-red-500" />
           <span className="text-[8px] mono text-gray-500 uppercase">MEV Bot Cluster</span>
        </div>
      </div>

      <svg ref={svgRef} className="absolute inset-0 w-full h-full cursor-grab active:cursor-grabbing z-10">
        <g transform={`translate(${transform.x}, ${transform.y}) scale(${transform.k})`}>
          <defs>
            <marker id="arrow-protected" markerWidth="10" markerHeight="8" refX="25" refY="4" orient="auto">
                <path d="M0,0 L0,8 L10,4 z" fill="rgba(99, 102, 241, 0.4)" />
            </marker>
            <marker id="arrow-routing" markerWidth="10" markerHeight="8" refX="25" refY="4" orient="auto">
                <path d="M0,0 L0,8 L10,4 z" fill="rgba(59, 130, 246, 0.2)" />
            </marker>
          </defs>

          {/* Links */}
          {links.map((link, i) => {
            const s = link.source as WalletNode;
            const t = link.target as WalletNode;
            if (s.x === undefined || t.x === undefined) return null;
            const active = isLinkActive(link);
            const dimmed = hoveredNode && !active;

            return (
              <g key={`flow-${i}`} className={`transition-opacity duration-700 ${dimmed ? 'opacity-5' : 'opacity-100'}`}>
                <line
                  x1={s.x} y1={s.y} x2={t.x} y2={t.y}
                  stroke={link.isProtected ? "#818cf8" : "#3b82f6"}
                  strokeOpacity={link.isProtected ? 0.4 : 0.2}
                  strokeWidth={link.isProtected ? "2" : "1.5"}
                  strokeDasharray={link.isProtected ? "0" : "4,4"}
                  marker-end={link.isProtected ? "url(#arrow-protected)" : "url(#arrow-routing)"}
                />
                <circle r={link.isProtected ? "2.5" : "1.5"} fill={link.isProtected ? "#818cf8" : "#3b82f6"}>
                  <animateMotion
                    dur={`${1 + Math.random() * 2}s`}
                    repeatCount="indefinite"
                    path={`M ${s.x},${s.y} L ${t.x},${t.y}`}
                  />
                </circle>
              </g>
            );
          })}

          {/* Nodes */}
          {nodes.map((node) => {
            const isHovered = hoveredNode?.id === node.id;
            const isNQ = node.id.includes('NQ-SWAP');
            const size = isNQ ? 120 : node.val * 2.2;
            const styles = getNodeStyles(node);

            return (
              <foreignObject
                key={node.id}
                x={(node.x ?? 0) - size / 2}
                y={(node.y ?? 0) - size / 2}
                width={size}
                height={size}
                className="overflow-visible pointer-events-auto"
              >
                <div
