                )}
              </foreignObject>
            );
          })}
        </g>
      </svg>

      {/* Global Partnership Legend */}
      <div className="h-20 border-t border-white/5 mt-auto flex items-center justify-between text-[8px] mono text-gray-500 uppercase tracking-[0.3em] px-12 bg-black/80 backdrop-blur-2xl z-30">
