import { ExecutionVenue } from '../types';

interface ExecutionModalProps {
  isOpen: boolean;
  onClose: () => void;
  token: any;
  userMode: string;
}

const VENUE_URLS: Record<ExecutionVenue, string> = {
  NQ_SWAP: 'https://nqswap.com',
  ASTER_DEX: 'https://asterdex.io',
  BINANCE: 'https://binance.com/en/trade',
  BYBIT: 'https://bybit.com/en/trade',
  UNISWAP_V4: 'https://app.uniswap.org'
};

const ExecutionModal: React.FC<ExecutionModalProps> = ({ isOpen, onClose, token, userMode }) => {
  const [view, setView] = useState<'TYPE_SELECT' | 'FIAT_FLOW' | 'CRYPTO_FLOW' | 'PENDING' | 'SUCCESS'>('TYPE_SELECT');
  const [isRouting, setIsRouting] = useState(false);
  const [selectedVenue, setSelectedVenue] = useState<ExecutionVenue | null>(null);

  // Reset state whenever modal opens to fix "stuck" issue
  useEffect(() => {
    if (isOpen) {
      setView('TYPE_SELECT');
      setSelectedVenue(null);
      setIsRouting(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleExternalRedirect = (venue: ExecutionVenue) => {
    setSelectedVenue(venue);
    setIsRouting(true);

    // 1. Open external platform in new tab
    const url = VENUE_URLS[venue];
    window.open(url, '_blank');

    // 2. Transition to "Pending" state on DFI Scope to await "hook" signal
    setTimeout(() => {
      setIsRouting(false);
      setView('PENDING');

      // 3. Simulate "Hook Signal" being received after 4-6 seconds
      setTimeout(() => {
        setView('SUCCESS');
      }, 5000);
    }, 800);
  };

  const handleFiatRedirect = (provider: string) => {
    window.open('https://www.moonpay.com/', '_blank');
    onClose();
  };

  const RenderVenue = ({ id, name, type, badge, best }: { id: ExecutionVenue, name: string, type: string, badge?: string, best?: boolean }) => (
    <button 
      onClick={() => handleExternalRedirect(id)}
      className={`w-full group p-5 rounded-[24px] border transition-all flex items-center justify-between mb-3 ${
        best ? 'bg-indigo-600/10 border-indigo-500/40' : 'bg-white/5 border-white/10 hover:border-white/20'
      }`}
    >
      <div className="flex items-center gap-4">
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${best ? 'bg-indigo-600' : 'bg-white/10'}`}>
          {best ? <Shield size={20} className="text-white" /> : <LinkIcon size={18} className="text-gray-400" />}
        </div>
        <div className="text-left">
          <div className="flex items-center gap-2">
            <span className="text-xs font-black text-white uppercase tracking-widest">{name}</span>
            {badge && <span className="text-[7px] font-black px-1.5 py-0.5 bg-indigo-500 text-white rounded">{badge}</span>}
          </div>
          <span className="text-[9px] text-gray-500 mono uppercase">{type} • Redirect to Node</span>
        </div>
      </div>
      <div className="flex items-center gap-4">
        {best && <div className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">Preferred Route</div>}
        <ExternalLink size={14} className="text-gray-600 group-hover:text-white transition-colors" />
      </div>
    </button>
  );

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 sm:p-0">
      <div className="absolute inset-0 bg-black/85 backdrop-blur-2xl animate-fade-in" onClick={onClose} />

      <div className="relative w-full max-w-[500px] bg-[#080808] border border-white/10 rounded-[40px] shadow-2xl overflow-hidden animate-pop-in">
        <header className="px-8 py-6 border-b border-white/5 flex justify-between items-center bg-white/5">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-indigo-600 rounded-lg">
                <ShoppingCart size={16} />
             </div>
             <div>
               <h2 className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Execution Matrix</h2>
               <p className="text-[9px] text-gray-500 mono font-bold uppercase">{token?.symbol} External Bridge</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/5 rounded-full transition-colors">
            <X size={20} className="text-gray-500" />
          </button>
        </header>

        <div className="p-8 min-h-[440px] flex flex-col">
          {view === 'TYPE_SELECT' && (
            <div className="space-y-6 animate-fade-in flex-1">
              <div className="mb-8">
                <h3 className="text-lg font-black text-white tracking-tight mb-2">Non-Custodial Dispatch</h3>
                <p className="text-xs text-gray-500 leading-relaxed">DFI Scope routes institutional data. Settlement occurs externally on vetted liquidity venues.</p>
              </div>

              <div className="grid grid-cols-1 gap-4">
                <button 
                  onClick={() => setView('FIAT_FLOW')}
                  className="group relative p-6 bg-white/5 border border-white/10 rounded-[32px] hover:bg-white/10 hover:border-emerald-500/30 transition-all text-left overflow-hidden"
                >
                  <div className="absolute -right-4 -bottom-4 opacity-5 text-white group-hover:opacity-10 transition-opacity">
                    <CreditCard size={120} />
                  </div>
                  <div className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl w-fit mb-4">
                    <CreditCard size={20} />
                  </div>
                  <h4 className="text-sm font-black text-white uppercase tracking-widest mb-1">Institutional On-Ramp</h4>
                  <p className="text-[10px] text-gray-500 mono">Connect Fiat via MoonPay / Stripe. Direct liquidity injection.</p>
                </button>

                <button 
                  onClick={() => setView('CRYPTO_FLOW')}
                  className="group relative p-6 bg-white/5 border border-white/10 rounded-[32px] hover:bg-white/10 hover:border-indigo-500/30 transition-all text-left overflow-hidden"
                >
                  <div className="absolute -right-4 -bottom-4 opacity-5 text-white group-hover:opacity-10 transition-opacity">
                    <Wallet size={120} />
                  </div>
                  <div className="p-3 bg-indigo-500/10 text-indigo-500 rounded-xl w-fit mb-4">
                    <Wallet size={20} />
                  </div>
                  <h4 className="text-sm font-black text-white uppercase tracking-widest mb-1">Market Venue Bridge</h4>
                  <p className="text-[10px] text-gray-500 mono">Bridge to NQ Swap, Binance, or DEX nodes for atomic execution.</p>
                </button>
              </div>
            </div>
          )}

          {view === 'FIAT_FLOW' && (
            <div className="animate-fade-in">
              <button onClick={() => setView('TYPE_SELECT')} className="text-[9px] text-indigo-400 font-black uppercase mb-6 flex items-center gap-2 hover:translate-x-1 transition-transform">
                <ChevronRight size={10} className="rotate-180" /> Back to Matrix
              </button>
              <h3 className="text-sm font-black text-white uppercase tracking-widest mb-6">Institutional Fiat Gateways</h3>
              <div className="space-y-4">
                {['MoonPay Institutional', 'Banxa Global', 'Stripe Treasury'].map((p) => (
                  <button key={p} onClick={() => handleFiatRedirect(p)} className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl flex justify-between items-center hover:bg-white/10 transition-all">
                    <div className="flex items-center gap-3">
                       <CreditCard size={14} className="text-emerald-500" />
                       <span className="text-xs font-bold text-white mono">{p}</span>
                    </div>
                    <ExternalLink size={14} className="text-gray-600" />
                  </button>
                ))}
              </div>
            </div>
          )}

          {view === 'CRYPTO_FLOW' && (
            <div className="animate-fade-in relative flex-1">
              {isRouting && (
                <div className="absolute inset-0 z-50 bg-[#080808]/95 flex flex-col items-center justify-center gap-6">
                  <RefreshCw size={48} className="text-indigo-500 animate-spin" />
                  <div className="text-center">
                    <p className="text-xs font-black text-white uppercase tracking-[0.4em]">Bridging to Node...</p>
                    <p className="text-[9px] text-gray-500 mono mt-2 animate-pulse">Establishing Session with {selectedVenue?.replace('_', ' ')}</p>
                  </div>
                </div>
              )}

              <button onClick={() => setView('TYPE_SELECT')} className="text-[9px] text-indigo-400 font-black uppercase mb-6 flex items-center gap-2 hover:translate-x-1 transition-transform">
                <ChevronRight size={10} className="rotate-180" /> Back to Matrix
              </button>
              <h3 className="text-sm font-black text-white uppercase tracking-widest mb-6">Execution Node Select</h3>

              <RenderVenue id="NQ_SWAP" name="NQ Swap House" type="Partner SOR" badge="Recommended" best />
              <RenderVenue id="ASTER_DEX" name="AsterDEX" type="Atomic Node" />
              <RenderVenue id="BINANCE" name="Binance Terminal" type="Global CEX" />
              <RenderVenue id="BYBIT" name="Bybit Terminal" type="Global CEX" />
              <RenderVenue id="UNISWAP_V4" name="Uniswap V4" type="DeFi Core" />
            </div>
          )}

          {view === 'PENDING' && (
            <div className="animate-fade-in flex flex-col items-center justify-center py-10 text-center flex-1">
               <div className="relative mb-10">
                  <Activity size={80} className="text-indigo-500 animate-pulse opacity-20" />
                  <div className="absolute inset-0 flex items-center justify-center">
                     <RefreshCw size={40} className="text-indigo-400 animate-spin" />
                  </div>
               </div>
               <h3 className="text-xl font-black text-white uppercase tracking-[0.2em] mb-4">Pending Hook Signal</h3>
               <p className="text-xs text-gray-500 max-w-[320px] leading-relaxed mb-4">
                 You have been redirected to <span className="text-white font-bold">{selectedVenue?.replace('_', ' ')}</span>.
               </p>
               <div className="bg-indigo-500/10 border border-indigo-500/20 px-6 py-4 rounded-2xl">
                 <p className="text-[9px] text-indigo-400 mono font-black uppercase animate-pulse">Awaiting cross-chain trade confirmation...</p>
               </div>
            </div>
          )}

          {view === 'SUCCESS' && (
            <div className="animate-fade-in flex flex-col items-center justify-center py-10 text-center flex-1">
               <div className="w-24 h-24 bg-emerald-500/20 rounded-full flex items-center justify-center mb-8 border border-emerald-500/30">
                  <CheckCircle2 size={48} className="text-emerald-500 drop-shadow-glow" />
               </div>
               <h3 className="text-2xl font-black text-white uppercase tracking-widest mb-3">Trade Executed</h3>
               <p className="text-xs text-gray-500 max-w-[300px] leading-relaxed mb-10">
                 External node confirmed settlement. Hook signal received. Anti-MEV monitoring for this position is now active in your dashboard.
               </p>
               <button 
                onClick={onClose}
                className="w-full py-5 bg-white text-black font-black uppercase text-[11px] tracking-[0.4em] rounded-full hover:bg-gray-200 transition-all active:scale-95 shadow-xl"
               >
                 Close Matrix Terminal
               </button>
            </div>
          )}
        </div>

        <footer className="px-8 py-5 border-t border-white/5 bg-black/40 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Shield size={12} className="text-indigo-500" />
            <span className="text-[8px] mono text-gray-500 uppercase">Non-Custodial External Routing</span>
          </div>
          <div className="flex items-center gap-4">
             <div className="text-[8px] mono text-gray-500 uppercase">Latency: <span className="text-emerald-500">OPTIMAL</span></div>
          </div>
        </footer>
      </div>

      <style>{`
        .drop-shadow-glow { filter: drop-shadow(0 0 10px rgba(16, 185, 129, 0.5)); }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes popIn { from { opacity: 0; transform: scale(0.95) translateY(10px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.3s ease-out forwards; }
        .animate-pop-in { animation: popIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

export default ExecutionModal;

import React, { useEffect, useRef, useState } from 'react';
import { Share2, Zap, AlertTriangle, Target, Box, Info, ArrowRightLeft, MousePointer2, Globe, Shield, RefreshCw, Layers, ZapOff, Activity } from 'lucide-react';
import * as d3 from 'd3';

interface WalletNode extends d3.SimulationNodeDatum {
  id: string;
  type: 'CORE' | 'SNIPER' | 'RETAIL';
  val: number;
  label?: string;
  noteType?: string;
  behaviorNote?: string;
  x?: number;
  y?: number;
}

interface WalletLink extends d3.SimulationLinkDatum<WalletNode> {
  source: string | WalletNode;
  target: string | WalletLink;
  flowValue?: number;
  isRouting?: boolean;
  isProtected?: boolean;
}

interface WalletGraphProps {
  data: {
    nodes: WalletNode[];
    links: WalletLink[];
  } | null;
}

const WalletGraph: React.FC<WalletGraphProps> = ({ data }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const [nodes, setNodes] = useState<WalletNode[]>([]);
  const [links, setLinks] = useState<WalletLink[]>([]);
  const [hoveredNode, setHoveredNode] = useState<WalletNode | null>(null);
  const [transform, setTransform] = useState({ x: 0, y: 0, k: 0.75 });

  useEffect(() => {
    if (!data || !containerRef.current || !svgRef.current) return;

    const width = containerRef.current.clientWidth;
    const height = containerRef.current.clientHeight;

    const simulationNodes: WalletNode[] = data.nodes.map(d => {
        let noteType = 'Latent Wallet';
        let behaviorNote = 'Standard retail activity detected.';

        if (d.id.includes('NQ')) {
            noteType = 'Institutional House';
            behaviorNote = 'NQ Swap core engine. Protected liquidity routing.';
        } else if (d.id.includes('Binance') || d.id.includes('Coinbase')) {
            noteType = 'Global Liquidity Hub';
            behaviorNote = 'High-volume CEX marketplace endpoint.';
        } else if (d.type === 'SNIPER') {
            noteType = 'MEV Arbitrageur';
            behaviorNote = 'Atomic bot cluster scanning for mempool slippage.';
        } else if (d.id.includes('Uni') || d.id.includes('Sushi')) {
            noteType = 'Liquidity Pool Node';
            behaviorNote = 'Decentralized automated market maker.';
        }

        return { ...d, noteType, behaviorNote };
    });
    const simulationLinks: WalletLink[] = data.links.map(d => ({ ...d }));

    const simulation = d3.forceSimulation<WalletNode>(simulationNodes)
      .force("link", d3.forceLink<WalletNode, WalletLink>(simulationLinks).id(d => d.id).distance(240))
      .force("charge", d3.forceManyBody().strength(-1800))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(d => (d as WalletNode).id.includes('NQ-SWAP') ? 85 : (d as WalletNode).val * 3.8));

    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 4])
      .on("zoom", (event) => setTransform(event.transform));

    d3.select(svgRef.current).call(zoom);

    simulation.on("tick", () => {
      setNodes([...simulationNodes]);
      setLinks([...simulationLinks]);
    });

    return () => simulation.stop();
  }, [data]);

  if (!data) return (
    <div className="h-full flex flex-col items-center justify-center opacity-20 text-center p-12 bg-[#0a0a0a] rounded-[32px] border border-white/5">
      <Share2 size={48} className="mb-4 text-gray-500" />
      <p className="text-xs font-black uppercase tracking-widest text-gray-500">Scan Required to Initialize Topology</p>
    </div>
  );

  const getNodeStyles = (node: WalletNode) => {
    const id = node.id;
    if (id.includes('NQ-SWAP')) return 'bg-gradient-to-br from-indigo-600 to-blue-900 border-indigo-400 shadow-[0_0_60px_rgba(79,70,229,0.5)] ring-4 ring-indigo-500/20';
    if (id.includes('Binance')) return 'bg-yellow-500 border-yellow-300 shadow-[0_0_40px_rgba(234,179,8,0.3)]';
    if (id.includes('Coinbase')) return 'bg-blue-500 border-blue-300 shadow-[0_0_40px_rgba(59,130,246,0.3)]';
    if (id.includes('Uni') || id.includes('Sushi')) return 'bg-pink-600 border-pink-400 shadow-[0_0_35px_rgba(219,39,119,0.2)]';

    switch (node.type) {
      case 'SNIPER': return 'bg-red-600 border-red-400 shadow-[0_0_20px_rgba(220,38,38,0.4)]';
      default: return 'bg-[#151515] border-white/10 shadow-none';
    }
  };

  const isLinkActive = (link: WalletLink) => {
    if (!hoveredNode) return true;
    const sourceId = typeof link.source === 'string' ? link.source : (link.source as any).id;
    const targetId = typeof link.target === 'string' ? link.target : (link.target as any).id;
    return sourceId === hoveredNode.id || targetId === hoveredNode.id;
  };

  return (
    <div className="h-full w-full relative overflow-hidden bg-[#030303] rounded-[32px] border border-white/5 flex flex-col" ref={containerRef}>

      {/* SOR Header Overlay */}
      <div className="absolute top-8 left-10 z-30 pointer-events-none">
        <div className="flex items-center gap-4 mb-2">
            <div className="p-2.5 bg-indigo-600 rounded-2xl shadow-xl border border-indigo-400/30">
                <Shield size={20} className="text-white animate-pulse" />
            </div>
            <div>
                <h3 className="text-[13px] font-black text-white uppercase tracking-[0.4em]">NQ SOR Infrastructure</h3>
                <p className="text-[10px] text-indigo-400 mono font-black uppercase flex items-center gap-2">
                   <Activity size={12} /> Institutional Traffic Verified
                </p>
            </div>
        </div>
      </div>

      {/* Dynamic Hierarchy Legend */}
      <div className="absolute left-10 bottom-24 z-30 flex flex-col gap-3 p-6 bg-black/70 backdrop-blur-2xl border border-white/10 rounded-[32px] min-w-[180px]">
        <h4 className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-1 px-1 border-b border-white/5 pb-2">Network Hierarchy</h4>
        {[
            { color: 'bg-indigo-600', label: 'NQ SOR HOUSE', shadow: 'shadow-indigo-500/40' },
            { color: 'bg-yellow-500', label: 'CEX MARKET HUB' },
            { color: 'bg-pink-600', label: 'DECENTRALIZED LP' },
            { color: 'bg-red-600', label: 'MEV CLUSTER', shadow: 'shadow-red-500/40' },
            { color: 'bg-gray-800', label: 'PRIVATE WALLET' }
        ].map((item, i) => (
            <div key={i} className="flex items-center gap-3 px-1 group cursor-default">
               <div className={`w-2.5 h-2.5 rounded-sm ${item.color} ${item.shadow ? `shadow-lg ${item.shadow}` : ''} transition-transform group-hover:scale-125`} />
               <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest group-hover:text-white transition-colors">{item.label}</span>
            </div>
        ))}
      </div>

      <svg ref={svgRef} className="absolute inset-0 w-full h-full cursor-grab active:cursor-grabbing z-10">
        <g transform={`translate(${transform.x}, ${transform.y}) scale(${transform.k})`}>
          <defs>
            <marker id="arrow-institutional" markerWidth="10" markerHeight="8" refX="28" refY="4" orient="auto">
                <path d="M0,0 L0,8 L10,4 z" fill="rgba(99, 102, 241, 0.5)" />
            </marker>
            <linearGradient id="nqGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="rgba(99, 102, 241, 0.4)" />
              <stop offset="100%" stopColor="rgba(99, 102, 241, 0)" />
            </linearGradient>
          </defs>

          {/* Links */}
          {links.map((link, i) => {
            const s = link.source as WalletNode;
            const t = link.target as WalletNode;
            if (s.x === undefined || t.x === undefined) return null;
            const active = isLinkActive(link);
            const dimmed = hoveredNode && !active;

            return (
              <g key={`flow-${i}`} className={`transition-opacity duration-700 ${dimmed ? 'opacity-5' : 'opacity-100'}`}>
                <line
                  x1={s.x} y1={s.y} x2={t.x} y2={t.y}
                  stroke={link.isProtected ? "url(#nqGrad)" : "rgba(255,255,255,0.05)"}
                  strokeWidth={link.isProtected ? "2.5" : "1"}
                  marker-end={link.isProtected ? "url(#arrow-institutional)" : ""}
                />
                <circle r={link.isProtected ? "2.2" : "1.2"} fill={link.isProtected ? "#818cf8" : "rgba(255,255,255,0.2)"}>
                  <animateMotion
                    dur={`${1.5 + Math.random() * 2}s`}
                    repeatCount="indefinite"
                    path={`M ${s.x},${s.y} L ${t.x},${t.y}`}
                  />
                </circle>
              </g>
            );
          })}

          {/* Nodes */}
          {nodes.map((node) => {
            const isHovered = hoveredNode?.id === node.id;
            const isNQ = node.id.includes('NQ-SWAP');
            const size = isNQ ? 130 : node.val * 2.5;
            const styles = getNodeStyles(node);

            return (
              <foreignObject
                key={node.id}
                x={(node.x ?? 0) - size / 2}
                y={(node.y ?? 0) - size / 2}
                width={size}
                height={size}
                className="overflow-visible pointer-events-auto"
              >
                <div
                  className={`w-full h-full rounded-full border-2 flex flex-col items-center justify-center transition-all duration-300 cursor-pointer ${styles}`}
                  style={{
                    transform: isHovered ? 'scale(1.15)' : 'scale(1)',
                    opacity: hoveredNode && hoveredNode.id !== node.id && !isLinkActive({source: hoveredNode, target: node} as any) ? 0.1 : 1,
                    zIndex: isHovered || isNQ ? 100 : 20,
                  }}
                  onMouseEnter={() => setHoveredNode(node)}
                  onMouseLeave={() => setHoveredNode(null)}
                >
                  {isNQ ? (
                    <div className="flex flex-col items-center justify-center">
                        <Shield size={size / 3.5} className="text-white mb-1 drop-shadow-lg" />
                        <span className="text-[10px] font-black text-white text-center leading-tight tracking-widest">NQ SWAP</span>
                    </div>
                  ) : (
                    <div className="flex items-center justify-center">
                        {node.id.includes('Binance') ? <span className="text-[10px] font-black text-black">BN</span> :
                         node.id.includes('Coinbase') ? <span className="text-[10px] font-black text-white">CB</span> :
                         node.type === 'SNIPER' ? <Zap size={16} className="text-white" /> :
                         <div className="w-2 h-2 rounded-full bg-white/20" />}
                    </div>
                  )}
                </div>

                {isHovered && (
                  <div className="absolute top-1/2 left-full ml-10 -translate-y-1/2 bg-[#0a0a0a]/95 border border-white/10 p-6 rounded-[32px] shadow-2xl backdrop-blur-3xl z-[300] min-w-[260px] pointer-events-none animate-pop-in">
                    <div className="flex items-center gap-4 mb-5 pb-3 border-b border-white/5">
                       <div className={`p-2 rounded-xl ${isNQ ? 'bg-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.4)]' : 'bg-gray-800'}`}>
                         {isNQ ? <Shield size={16} /> : node.type === 'SNIPER' ? <ZapOff size={16} /> : <Layers size={16} />}
                       </div>
                       <div>
                        <span className="text-[12px] font-black text-white uppercase tracking-widest block mb-0.5">{node.label}</span>
                        <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">{node.noteType}</span>
                       </div>
                    </div>

                    <div className="space-y-4">
                      <div className="bg-white/5 p-3.5 rounded-2xl border border-white/5">
                        <span className="text-[9px] text-gray-500 font-black uppercase tracking-widest block mb-1.5">Behavior Insight</span>
                        <p className="text-[10px] text-gray-200 leading-relaxed mono">{node.behaviorNote}</p>
                      </div>

                      <div className="flex justify-between items-center px-2">
                        <span className="text-[9px] text-gray-600 font-black uppercase">Node Valuation</span>
