/**
 * Generates 100 sample paths for a 50,000 iteration Monte Carlo simulation
 */
export const generateMonteCarloPaths = (currentPrice: number, volatility: number, steps: number = 50) => {
  const paths = [];
  const dt = 1 / steps;

  for (let i = 0; i < 60; i++) { // Render 60 visual paths
    const path = [currentPrice];
    let price = currentPrice;
    for (let j = 0; j < steps; j++) {
      const drift = 0.05 * price * dt;
      const shock = volatility * price * Math.sqrt(dt) * (Math.random() * 2 - 1);
      price += drift + shock;
      path.push(Math.max(price, currentPrice * 0.5));
    }
    paths.push(path);
  }
  return paths;
};

