    { id: `MM-1`, group: 4, val: 80, type: 'CORE', label: isInst ? 'Robinhood Flow Source' : 'BlackRock Proxy' },
    { id: `MM-2`, group: 4, val: 75, type: 'CORE', label: isInst ? 'Phantom Wallet Cluster' : 'Jump Trading Node' },
  ];

  const links: WalletLinkData[] = [];
  nodes.forEach(n => links.push({ source: n.id, target: `HUB-CORE`, flowValue: 1000, isRouting: true }));

  const count = isInst ? 30 : 20;
  for (let i = 0; i < count; i++) {
