const generateInstitutionalAnalytics = (hash: number): InstitutionalAnalytics => {
  return {
    mevRank: 40 + (hash % 60),
    mevOpportunities: [
      { venue: 'Raydium/Binance', spread: 2.2, liquidity: 500000, status: 'ACTIVE' },
      { venue: 'Orca/Bybit', spread: 1.8, liquidity: 350000, status: 'ACTIVE' },
      { venue: 'Jupiter Mixed', spread: 2.2, liquidity: 1200000, status: 'ACTIVE' }
    ],
    poolExpansionScore: 30 + (hash % 70),
    poolSuggestions: [
      { dex: 'Raydium CLMM', range: '$0.85 - $1.15', suggestedAmount: 50000, projectedApr: 145 },
      { dex: 'Meteora DLMM', range: 'Active Bin: 45', suggestedAmount: 100000, projectedApr: 210 }
    ],
    exploitProbability: (hash % 10) / 2,
    vulnerabilityReport: hash % 10 < 3 
      ? "Code contains potential overflow in mint function. Re-entrancy risk detected in hook."
      : "Low vulnerability in contract bytecode for current patch. Verified SPL-Token standard."
  };
};

const generateSecurityAudit = (address: string, chain: string): SecurityAudit => {
  const isSolana = chain === 'solana';
  const hash = address.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

  const creator: CreatorProfile = {
    address: `${isSolana ? 'Sol' : '0x'}${Math.random().toString(16).slice(2, 10)}...`,
    associatedAccounts: 2 + (hash % 15),
    pastProjectsCount: hash % 10,
    trustIndex: hash % 5 === 0 ? 'DANGER' : (hash % 3 === 0 ? 'STABLE' : 'ELITE')
  };

  return {
    isLiquidityLocked: hash % 3 !== 0,
    lockDuration: hash % 3 !== 0 ? '365 Days' : undefined,
    rugProbability: hash % 5 === 0 ? 'HIGH' : (hash % 3 === 0 ? 'MEDIUM' : 'LOW'),
    honeypotCheck: 'PASSED',
    topHoldersPercent: 12 + (hash % 35),
    mintAuthorityRevoked: isSolana ? (hash % 2 === 0) : true,
    creator: creator
  };
};

export const fetchTokenByAddress = async (address: string): Promise<EnhancedTokenData | null> => {
  const cleanAddress = address.trim();
  const hash = cleanAddress.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

  try {
    const dexRes = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${cleanAddress}`);
    if (dexRes.ok) {
      const data = await dexRes.json();
      if (data.pairs && data.pairs.length > 0) {
        const bestPair = data.pairs.sort((a: any, b: any) => (b.liquidity?.usd || 0) - (a.liquidity?.usd || 0))[0];
        const chainId = bestPair.chainId;

        return {
          id: bestPair.baseToken.address,
          symbol: bestPair.baseToken.symbol.toUpperCase(),
          name: bestPair.baseToken.name,
          priceUsd: parseFloat(bestPair.priceUsd) || 0,
          priceChange24h: bestPair.priceChange?.h24 || 0,
          marketCap: bestPair.fdv || 0,
          volume24h: bestPair.volume?.h24 || 0,
          image: bestPair.info?.imageUrl || `https://ui-avatars.com/api/?name=${bestPair.baseToken.symbol}&background=random`,
          isSimulated: false,
          sector: SECTORS[Math.floor(Math.random() * SECTORS.length)],
          volatility: 0.4 + Math.random() * 0.6,
          dominance: 0.01,
          mktMakerActivity: Math.random() > 0.4 ? 'HIGH' : 'MEDIUM',
          chain: chainId,
          dexName: bestPair.dexId,
          security: generateSecurityAudit(bestPair.baseToken.address, chainId),
          instAnalytics: generateInstitutionalAnalytics(hash)
        };
      }
    }
  } catch (err) {
    console.warn("DexScreener failed, using fallback.");
  }

  const isEth = /^0x[a-fA-F0-9]{40}$/.test(cleanAddress);
  const isSol = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(cleanAddress);

  if (isEth || isSol) {
    const chain = isEth ? 'ethereum' : 'solana';
    return {
      id: `deep-scan-${cleanAddress}`,
      symbol: isEth ? 'EVM-UNKN' : 'SOL-UNKN',
      name: `Deep Scan: ${cleanAddress.slice(0, 8)}...`,
      priceUsd: 0.0001 + Math.random() * 10,
      priceChange24h: (Math.random() - 0.4) * 50,
      marketCap: 50000 + Math.random() * 500000,
      volume24h: 10000 + Math.random() * 100000,
      image: isEth 
        ? "https://assets.coingecko.com/coins/images/279/large/ethereum.png"
        : "https://assets.coingecko.com/coins/images/4128/large/solana.png",
      isSimulated: true,
      sector: 'Unlisted',
      volatility: 0.95,
      dominance: 0.0001,
      mktMakerActivity: 'LOW',
      chain: chain,
      security: generateSecurityAudit(cleanAddress, chain),
      instAnalytics: generateInstitutionalAnalytics(hash)
    };
  }

  return null;
};

export const fetchTopMarkets = async (page: number = 1): Promise<TokenData[]> => {
  try {
    const res = await fetch(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=${page}&sparkline=false`);
