const generateSecurityAudit = (address: string, chain: string): SecurityAudit => {
  const isSolana = chain === 'solana';
  const hash = address.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

  const creator: CreatorProfile = {
    address: `${isSolana ? 'Sol' : '0x'}${Math.random().toString(16).slice(2, 10)}...`,
    associatedAccounts: 1 + (hash % 20),
    pastProjectsCount: hash % 12,
    trustIndex: hash % 6 === 0 ? 'DANGER' : (hash % 4 === 0 ? 'STABLE' : 'ELITE')
  };

  return {
    isLiquidityLocked: hash % 4 !== 0,
    lockDuration: hash % 4 !== 0 ? '365 Days' : undefined,
    rugProbability: hash % 7 === 0 ? 'HIGH' : (hash % 4 === 0 ? 'MEDIUM' : 'LOW'),
    honeypotCheck: 'PASSED',
    topHoldersPercent: 10 + (hash % 45),
    mintAuthorityRevoked: isSolana ? (hash % 3 === 0) : true,
    creator: creator
  };
};

export const fetchTokenByAddress = async (address: string): Promise<EnhancedTokenData | null> => {
  const cleanAddress = address.trim();
  const hash = cleanAddress.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);

  try {
    const dexRes = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${cleanAddress}`);
    if (dexRes.ok) {
      const data = await dexRes.json();
      if (data.pairs && data.pairs.length > 0) {
        const bestPair = data.pairs.sort((a: any, b: any) => (b.liquidity?.usd || 0) - (a.liquidity?.usd || 0))[0];
        const chainId = bestPair.chainId;

        return {
          id: bestPair.baseToken.address,
          symbol: bestPair.baseToken.symbol.toUpperCase(),
          name: bestPair.baseToken.name,
          priceUsd: parseFloat(bestPair.priceUsd) || 0,
          priceChange24h: bestPair.priceChange?.h24 || 0,
          marketCap: bestPair.fdv || 0,
          volume24h: bestPair.volume?.h24 || 0,
          image: bestPair.info?.imageUrl || `https://ui-avatars.com/api/?name=${bestPair.baseToken.symbol}&background=random`,
          isSimulated: false,
          sector: SECTORS[Math.floor(Math.random() * SECTORS.length)],
          volatility: 0.2 + Math.random() * 1.5,
          dominance: 0.01,
          mktMakerActivity: Math.random() > 0.4 ? 'HIGH' : 'MEDIUM',
          chain: chainId,
          dexName: bestPair.dexId,
          security: generateSecurityAudit(bestPair.baseToken.address, chainId),
          instAnalytics: generateInstitutionalAnalytics(hash),
          socialMetrics: generateSocialMetrics(hash)
        };
      }
    }
  } catch (err) {
    console.warn("DexScreener API failure.");
  }
  return null;
};

