const ExploitScannerLog: React.FC<{ probability: number, report: string }> = ({ probability, report }) => {
  const [lines, setLines] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setLines([]); 
    const potentialLines = [
      "[INFO] INITIALIZING DEEP BYTECODE ARCHEOLOGY...",
      "[SCAN] FETCHING CONTRACT METADATA FROM ON-CHAIN RPC...",
      "[OK] CONTRACT DETECTED: MAINNET VERIFIED",
      "[SCAN] SEARCHING FOR RE-ENTRANCY VECTORS...",
      "[SAFE] NO EXTERNAL CALLS FOUND IN CRITICAL LOOPS",
      "[SCAN] ANALYZING MINT AUTHORITY AND OWNERSHIP...",
      probability > 7 ? "[ALERT] MINT AUTHORITY IS NOT REVOKED" : "[OK] OWNERSHIP RENOUNCED / MULTISIG VERIFIED",
      "[SCAN] CHECKING LIQUIDITY LOCKERS (UNICRYPT/TEAM.FINANCE)...",
      "[INFO] DETECTED LOCKER SESSION ID: #SOL-8822-X",
      "[OK] TOP HOLDERS CONCENTRATION: ANALYZING...",
      "[SCAN] SEARCHING FOR HIDDEN BLACKLIST FUNCTIONS...",
      probability > 5 ? "[WARNING] DETECTED OBFUSCATED LOGIC IN _TRANSFER" : "[OK] NO BLACKLIST LOGIC DETECTED",
      "[SCAN] COMPARING BYTECODE AGAINST KNOWN SCAM TEMPLATES...",
      `[RESULT] VULNERABILITY REPORT: ${report || 'N/A'}`,
      "[COMPLETED] SOVEREIGN SCAN FINISHED."
    ];
    let i = 0;
    const interval = setInterval(() => {
      if (i < potentialLines.length) {
        setLines(prev => [...prev, potentialLines[i]]);
        i++;
      } else {
        clearInterval(interval);
      }
    }, 120);
    return () => clearInterval(interval);
  }, [probability, report]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [lines]);

  return (
    <div ref={scrollRef} className="bg-black/90 rounded-[28px] p-8 font-mono text-[10px] h-80 overflow-y-auto border border-white/5 shadow-inner scrollbar-hide">
      {lines.map((l, i) => {
        const isAlert = l && typeof l === 'string' && (l.includes('ALERT') || l.includes('WARNING') || l.includes('HIGH RISK'));
        const isOk = l && typeof l === 'string' && (l.includes('OK') || l.includes('SUCCESS') || l.includes('SECURE'));
        return (
          <div key={i} className={`mb-2 flex gap-4 ${isAlert ? 'text-red-500' : isOk ? 'text-emerald-500' : 'text-gray-600'}`}>
            <span className="opacity-20 shrink-0">[{new Date().toLocaleTimeString()}]</span>
            <span className="leading-relaxed">{l}</span>
          </div>
        );
      })}
      <div className="w-1.5 h-3 bg-blue-500 inline-block animate-pulse ml-1" />
    </div>
  );
};

