import React, { useRef, useEffect, useState } from 'react';

interface MonteCarloPathsProps {
  paths: number[][];
  width: number;
  height: number;
}

const MonteCarloPaths: React.FC<MonteCarloPathsProps> = ({ paths, width, height }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [progress, setProgress] = useState(0);
  const animationStartTimeRef = useRef<number>(0);

  useEffect(() => {
    setProgress(0);
    animationStartTimeRef.current = performance.now();
    let animationFrame: number;

    const animateLabel = () => {
      const elapsed = performance.now() - animationStartTimeRef.current;
      const totalDuration = 3000; 
      const p = Math.min(elapsed / totalDuration, 1);
      setProgress(p);
      if (p < 1) {
        animationFrame = requestAnimationFrame(animateLabel);
      }
    };

    animationFrame = requestAnimationFrame(animateLabel);
    return () => cancelAnimationFrame(animationFrame);
  }, [paths]);

  useEffect(() => {
    if (!canvasRef.current || paths.length === 0) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    let renderFrame: number;
    const pathDuration = 1000; // Time for one path to fully draw
    const staggerDelay = 25;   // Delay between consecutive paths starting

    const render = (time: number) => {
      const elapsed = time - animationStartTimeRef.current;
      ctx.clearRect(0, 0, width, height);

      const allPrices = paths.flat();
      const minPrice = Math.min(...allPrices);
      const maxPrice = Math.max(...allPrices);
      const range = (maxPrice - minPrice) || 1;

      // 1. Draw Static Grid Infrastructure
      ctx.strokeStyle = 'rgba(255,255,255,0.03)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = (i / 4) * height;
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
      }

      // 2. Staggered Path Drawing with Shimmer
      paths.forEach((path, i) => {
        // Calculate relative start time for this specific path
        const pathStart = i * staggerDelay;
        const pathElapsed = elapsed - pathStart;

        if (pathElapsed <= 0) return;

        // Progress for this path (0 to 1)
        const pathProgress = Math.min(pathElapsed / pathDuration, 1);
        const visibleSteps = Math.floor(path.length * pathProgress);

        if (visibleSteps < 2) return;

        const isUp = path[path.length - 1] > path[0];

        // Dynamic Shimmer Logic
        // We use sine waves based on time and path index to shift color intensity
        const shimmer = Math.sin((time / 300) + (i * 0.5)) * 0.05;
        const baseAlpha = 0.08 + (i / paths.length) * 0.12;
        const finalAlpha = Math.max(0.02, baseAlpha + shimmer);

        ctx.beginPath();
        ctx.strokeStyle = isUp 
          ? `rgba(34, 197, 94, ${finalAlpha})`
          : `rgba(239, 68, 68, ${finalAlpha})`;

        // Slightly thicker line for the drawing "head" to enhance shimmer
        ctx.lineWidth = pathProgress < 1 ? 1.5 : 1;

        for (let step = 0; step < visibleSteps; step++) {
          const x = (step / (path.length - 1)) * width;
          const y = height - ((path[step] - minPrice) / range) * height;
          if (step === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();

        // 3. Sequential Highlight (Glowing point at the head of incomplete paths)
        if (pathProgress > 0 && pathProgress < 1) {
          const headIdx = visibleSteps - 1;
          const hX = (headIdx / (path.length - 1)) * width;
          const hY = height - ((path[headIdx] - minPrice) / range) * height;

          ctx.beginPath();
          ctx.fillStyle = isUp ? `rgba(34, 197, 94, 0.4)` : `rgba(239, 68, 68, 0.4)`;
          ctx.arc(hX, hY, 1.5, 0, Math.PI * 2);
          ctx.fill();
        }
      });

      // 4. Final Aggregated Equilibrium (Mean Projection)
      if (progress > 0.8) {
        const lastPrices = paths.map(p => p[p.length - 1]);
        const avgLast = lastPrices.reduce((a, b) => a + b, 0) / lastPrices.length;
        const avgY = height - ((avgLast - minPrice) / range) * height;

        // Fade in the average line
        const avgAlpha = (progress - 0.8) * 5; 
        ctx.beginPath();
        ctx.strokeStyle = `rgba(74, 222, 128, ${avgAlpha * 0.5})`;
        ctx.setLineDash([5, 5]);
        ctx.lineWidth = 1.5;
        ctx.moveTo(0, avgY);
        ctx.lineTo(width, avgY);
        ctx.stroke();
        ctx.setLineDash([]);
      }

      renderFrame = requestAnimationFrame(render);
    };

    renderFrame = requestAnimationFrame(render);
    return () => cancelAnimationFrame(renderFrame);
  }, [paths, width, height, progress]);

  return (
    <div className="relative group bg-[#050505] rounded-[40px] border border-white/5 p-1 overflow-hidden shadow-inner">
      <div className="absolute top-6 left-8 z-20 pointer-events-none">
        <div className="flex items-center gap-4">
           <div className={`w-2 h-2 rounded-full ${progress < 1 ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'} shadow-[0_0_10px_currentColor]`} />
           <span className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] mono">
             {progress < 1 ? 'Propagating Scenarios' : 'Simulation Complete'}: {Math.floor(progress * 100)}%
           </span>
        </div>
      </div>
      <div className="relative">
        <canvas 
          ref={canvasRef} 
          width={width} 
          height={height} 
          className="w-full h-auto cursor-crosshair opacity-90 transition-opacity hover:opacity-100 mix-blend-screen"
        />
        {/* Subtle vignette/bloom overlay */}
        <div className="absolute inset-0 pointer-events-none bg-gradient-to-t from-black/20 via-transparent to-transparent" />
      </div>
    </div>
  );
};

