import React, { useRef, useEffect } from 'react';
import { calculateGAF, calculateMTF } from '../utils/math';

interface RetinaDisplayProps {
  data: number[];
  type: 'GAF' | 'MTF' | 'Recurrence';
}

const RetinaDisplay: React.FC<RetinaDisplayProps> = ({ data, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);

  useEffect(() => {
    if (!canvasRef.current || data.length === 0) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const matrix = type === 'GAF' ? calculateGAF(data) : calculateMTF(data);
    const size = matrix.length;
    const canvasSize = 400;
    const cellSize = canvasSize / size;

    canvasRef.current.width = canvasSize;
    canvasRef.current.height = canvasSize;

    let offset = 0;
    const animate = () => {
      offset += 0.02;
      ctx.clearRect(0, 0, canvasSize, canvasSize);

      // Background
      ctx.fillStyle = '#050508';
      ctx.fillRect(0, 0, canvasSize, canvasSize);

      // Matrix
      for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
          const val = matrix[i][j];
          const intensity = Math.floor(((val + 1) / 2) * 255);

          if (type === 'GAF') {
            const r = Math.floor(intensity * 0.2);
            const g = intensity;
            const b = 255;
            ctx.fillStyle = `rgba(${r}, ${g}, ${b}, 0.7)`;
          } else {
            ctx.fillStyle = `rgba(0, 240, 255, ${val * 0.9})`;
          }
          ctx.fillRect(i * cellSize, j * cellSize, cellSize - 0.5, cellSize - 0.5);
        }
      }

      // Scanning line
      const scanY = (offset * 100) % canvasSize;
      ctx.strokeStyle = 'rgba(0, 240, 255, 0.4)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, scanY);
      ctx.lineTo(canvasSize, scanY);
      ctx.stroke();

      requestRef.current = requestAnimationFrame(animate);
    };

    animate();
    return () => cancelAnimationFrame(requestRef.current);
  }, [data, type]);

  return (
    <div className="glass rounded-[40px] p-8 flex flex-col items-center relative overflow-hidden h-[550px] justify-center">
      <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500/20" />
      <h3 className="text-[10px] font-black text-cyan-500 uppercase tracking-[0.4em] mb-6 mono">
        Retina Spectrogram // {type}
      </h3>
      <div className="relative p-1 bg-white/5 rounded-2xl border border-white/10 shadow-[0_0_40px_rgba(0,240,255,0.05)]">
        <canvas ref={canvasRef} className="rounded-xl" />
      </div>
      <div className="mt-8 flex items-center gap-3">
        <Monitor size={14} className="text-cyan-500 animate-pulse" />
        <span className="text-[9px] mono text-gray-500 uppercase tracking-widest font-black">Scanning MEV Node Entropy...</span>
      </div>
    </div>
  );
};

export default RetinaDisplay;

