const KineticCounter: React.FC<{ base: number; prefix?: string; suffix?: string; isProfit?: boolean; theme: Theme }> = ({ base, prefix = "", suffix = "", isProfit, theme }) => {
  const [displayValue, setDisplayValue] = useState(base);
  const isDark = theme === 'DARK';

  useEffect(() => {
    let count = 0;
    const roulette = setInterval(() => {
      setDisplayValue(Math.floor(Math.random() * base * 2));
      count++;
      if (count > 15) {
        clearInterval(roulette);
        setDisplayValue(base);
        const incrementer = setInterval(() => {
          setDisplayValue(prev => prev + Math.floor(Math.random() * 85000));
        }, 150);
        return () => clearInterval(incrementer);
      }
    }, 60);
    return () => clearInterval(roulette);
  }, [base]);

  return (
    <div className="flex flex-col items-center">
      <span className={`text-5xl md:text-7xl font-black italic mono tracking-tighter tabular-nums ${isProfit ? 'text-emerald-500' : isDark ? 'text-white' : 'text-slate-950'}`}>
        {prefix}{displayValue.toLocaleString()}{suffix}
      </span>
      <div className={`h-1 w-full mt-2 bg-gradient-to-r from-transparent ${isProfit ? 'via-emerald-500/50' : 'via-cyan-500/50'} to-transparent`} />
    </div>
  );
};

