export const fetchTopMarkets = async (count: number = 272): Promise<EnhancedTokenData[]> => {
  try {
    // Fetching enough pages to reach 272 unique assets
    const pages = Math.ceil(count / 100);
    let allAssets: any[] = [];

    for (let p = 1; p <= pages; p++) {
      const res = await fetch(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=100&page=${p}&sparkline=false`);
      if (res.ok) {
        const data = await res.json();
        allAssets = [...allAssets, ...data];
      }
      // Simple rate limit protection
      if (pages > 1) await new Promise(r => setTimeout(r, 200));
    }

    // Ensure uniqueness and slice to exact count
    const uniqueMap = new Map();
    allAssets.forEach(item => {
      if (!uniqueMap.has(item.id)) uniqueMap.set(item.id, item);
    });

    const finalAssets = Array.from(uniqueMap.values()).slice(0, count);

    return finalAssets.map((item: any) => {
      const hash = item.id.split('').reduce((acc: number, char: string) => acc + char.charCodeAt(0), 0);

      // Triple Bull Logic: Simulated but deterministic based on hash/id for consistency
      const isTripleBull = (hash % 10 === 0) || (item.price_change_percentage_24h > 1.5 && hash % 4 === 0);

      return {
        id: item.id,
        symbol: item.symbol.toUpperCase(),
        name: item.name,
        priceUsd: item.current_price || 0,
        priceChange24h: item.price_change_percentage_24h || 0,
        marketCap: item.market_cap || 0,
        volume24h: item.total_volume || 0,
        image: item.image,
        rank: item.market_cap_rank,
        sector: SECTORS[hash % SECTORS.length],
        volatility: 0.1 + (hash % 90) / 100,
        dominance: (item.market_cap / 1e12) * 100,
        mktMakerActivity: (hash % 3 === 0) ? 'HIGH' : 'LOW',
        socialMetrics: generateSocialMetrics(hash),
        instAnalytics: generateInstitutionalAnalytics(hash, item.symbol.toUpperCase()),
        isTripleBull
      };
    });
  } catch (e) {
    console.error("CoinGecko Service Failure:", e);
  }
  return [];
};

