const TradingViewChart: React.FC<{ symbol: string; theme: Theme }> = ({ symbol, theme }) => {
  const containerId = `tv_chart_${symbol}_${Math.random().toString(36).substr(2, 9)}`;

  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/tv.js';
    script.async = true;
    script.onload = () => {
      // Fix: Cast window to any to access TradingView property injected by external script
      if ((window as any).TradingView) {
        new (window as any).TradingView.widget({
          width: '100%',
          height: 450,
          symbol: `BINANCE:${symbol}USDT`,
          interval: 'D',
          timezone: 'Etc/UTC',
          theme: theme === 'DARK' ? 'dark' : 'light',
          style: '1',
          locale: 'en',
          toolbar_bg: '#f1f3f6',
          enable_publishing: false,
          hide_top_toolbar: false,
          hide_legend: false,
          save_image: false,
          container_id: containerId,
          backgroundColor: theme === 'DARK' ? '#08080c' : '#ffffff',
          gridColor: theme === 'DARK' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.05)',
        });
      }
    };
    document.head.appendChild(script);
  }, [symbol, theme]);

  return <div id={containerId} className="w-full rounded-[32px] overflow-hidden border border-white/5" />;
};

