  }, [base]);

  return (
    <div className="flex flex-col items-center">
      <span className={`text-5xl md:text-7xl font-black italic mono tracking-tighter tabular-nums ${isProfit ? 'text-emerald-500' : isDark ? 'text-white' : 'text-slate-950'}`}>
