/**
 * Fetches exactly 272 unique crypto assets from CoinGecko.
 * Each asset is evaluated for "Triple Bullish" status (Simulated Multi-Timeframe alignment).
 */
export const fetchTopMarkets = async (count: number = 272): Promise<EnhancedTokenData[]> => {
  try {
    const uniqueAssetsMap = new Map();
    let page = 1;

    // Continue fetching until we have at least 'count' unique assets
    while (uniqueAssetsMap.size < count && page < 5) {
      const res = await fetch(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=250&page=${page}&sparkline=false`);
      if (res.ok) {
        const data = await res.json();
        if (data.length === 0) break;
        data.forEach((item: any) => {
          if (!uniqueAssetsMap.has(item.id)) {
            uniqueAssetsMap.set(item.id, item);
          }
        });
      } else {
        break;
      }
      page++;
      // Basic sleep to avoid excessive rate limiting during initialization
      await new Promise(r => setTimeout(r, 200));
    }

    const finalAssets = Array.from(uniqueAssetsMap.values()).slice(0, count);

    return finalAssets.map((item: any) => {
      // Deterministic hash based on ID for consistent simulation properties
      const hash = item.id.split('').reduce((acc: number, char: string) => acc + char.charCodeAt(0), 0);

      // Triple Bull Logic: Asset must have positive 24h change AND meet specific "Sovereign" structural criteria
      // In a real gov app, this would involve fetching separate D/W/M candle data
      const isTripleBull = (item.price_change_percentage_24h > 1.2 && (hash % 8 === 0)) || (hash % 15 === 0);

      return {
        id: item.id,
        symbol: item.symbol.toUpperCase(),
        name: item.name,
        priceUsd: item.current_price || 0,
        priceChange24h: item.price_change_percentage_24h || 0,
        marketCap: item.market_cap || 0,
        volume24h: item.total_volume || 0,
        image: item.image,
        rank: item.market_cap_rank,
        sector: SECTORS[hash % SECTORS.length],
        volatility: 0.1 + (hash % 90) / 100,
        dominance: (item.market_cap / 1e12) * 100,
        mktMakerActivity: (hash % 3 === 0) ? 'HIGH' : 'LOW',
        socialMetrics: generateSocialMetrics(hash),
        instAnalytics: generateInstitutionalAnalytics(hash, item.symbol.toUpperCase()),
        isTripleBull
      };
    });
  } catch (e) {
    console.error("CoinGecko Sovereign Node Failure:", e);
    return [];
  }
};

