/**
 * Calculates Recurrence Plot matrix
 */
export const calculateRecurrence = (data: number[], threshold: number = 0.1): number[][] => {
  const n = data.length;
  if (n === 0) return [];

  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      const dist = Math.abs(data[i] - data[j]);
      row.push(dist < threshold ? 1 : 0);
    }
    matrix.push(row);
  }
  return matrix;
};

/**
 * Institutional Signal Helpers
 */
export const calculateZScore = (val: number, mean: number, std: number) => (val - mean) / std;

export const calculateKelly = (prob: number, winLossRatio: number) => {
  const q = 1 - prob;
  return (prob * winLossRatio - q) / winLossRatio;
};

export const generateSORData = (totalAmount: number) => {
  const splits = 8;
  const childOrders = [];
  let remaining = totalAmount;
  for (let i = 0; i < splits; i++) {
    const amount = i === splits - 1 ? remaining : (totalAmount / splits) * (0.8 + Math.random() * 0.4);
    childOrders.push({
      id: `ord-${i}`,
      venue: i % 2 === 0 ? 'Binance' : 'NQ Swap',
      amount,
      status: i < 3 ? 'FILLED' : i === 3 ? 'ACTIVE' : 'PENDING'
    });
    remaining -= amount;
  }
  return childOrders;
};

