import React, { useRef, useEffect, useState } from 'react';
import { calculateGAF, calculateMTF, calculateRecurrence } from '../utils/math';
import { Monitor, ShieldAlert, Target, Box } from 'lucide-react';

interface RetinaDisplayProps {
  data: number[];
  type: 'GAF' | 'MTF' | 'RECURRENCE';
}

const RetinaDisplay: React.FC<RetinaDisplayProps> = ({ data, type }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>(0);
  const [detectedPattern, setDetectedPattern] = useState<{name: string, confidence: number} | null>(null);

  useEffect(() => {
    if (!canvasRef.current || data.length === 0) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const matrix = type === 'GAF' ? calculateGAF(data) : type === 'MTF' ? calculateMTF(data) : calculateRecurrence(data);
    const size = matrix.length;
    const canvasSize = 400;
    const cellSize = canvasSize / size;

    canvasRef.current.width = canvasSize;
    canvasRef.current.height = canvasSize;

    // Simulate Computer Vision Pattern Recognition
    if (Math.random() > 0.7) {
      setDetectedPattern({ name: 'WYCKOFF_SPRING', confidence: 0.85 + Math.random() * 0.1 });
    }

    let offset = 0;
    const animate = () => {
      offset += 0.02;
      ctx.clearRect(0, 0, canvasSize, canvasSize);
      ctx.fillStyle = '#050508';
      ctx.fillRect(0, 0, canvasSize, canvasSize);

      for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
          const val = matrix[i][j];
          if (type === 'GAF') {
            const intensity = Math.floor(((val + 1) / 2) * 255);
            ctx.fillStyle = `rgba(0, ${intensity}, 255, 0.7)`;
          } else if (type === 'MTF') {
            ctx.fillStyle = `rgba(0, 240, 255, ${val * 0.9})`;
          } else {
            ctx.fillStyle = val === 1 ? 'rgba(112, 0, 255, 0.8)' : 'rgba(255, 255, 255, 0.02)';
          }
          ctx.fillRect(i * cellSize, j * cellSize, cellSize - 0.5, cellSize - 0.5);
        }
      }

      // YOLO v8 Bounding Box Simulation
      if (detectedPattern) {
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(50, 50, 150, 150);
        ctx.fillStyle = '#22c55e';
        ctx.font = '10px JetBrains Mono';
        ctx.fillText(`${detectedPattern.name} (${(detectedPattern.confidence * 100).toFixed(1)}%)`, 55, 45);
        ctx.setLineDash([]);
      }

      const scanY = (offset * 100) % canvasSize;
      ctx.strokeStyle = 'rgba(0, 240, 255, 0.3)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, scanY);
      ctx.lineTo(canvasSize, scanY);
      ctx.stroke();

      requestRef.current = requestAnimationFrame(animate);
    };

    animate();
    return () => cancelAnimationFrame(requestRef.current);
  }, [data, type]);

  return (
    <div className="glass rounded-[48px] p-10 flex flex-col items-center relative overflow-hidden h-[550px] justify-center shadow-2xl border-white/5 bg-[#08080c]">
      <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500/20 shadow-[0_0_10px_cyan]" />
      <div className="flex justify-between w-full mb-8 px-4">
        <h3 className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.5em] mono">
          Retina Spectrogram // {type}
        </h3>
        {detectedPattern && (
          <div className="flex items-center gap-2 text-emerald-500 animate-pulse">
            <Box size={14} />
            <span className="text-[10px] font-black mono uppercase">CNN Detect: Active</span>
          </div>
        )}
      </div>
      <div className="relative p-2 bg-white/5 rounded-[32px] border border-white/10 shadow-[0_0_60px_rgba(0,240,255,0.1)]">
        <canvas ref={canvasRef} className="rounded-2xl" />
      </div>
      <div className="mt-10 flex items-center gap-3">
        <Monitor size={14} className="text-cyan-400" />
        <span className="text-[9px] mono text-gray-500 uppercase tracking-widest font-black">Temporal Correlation Resolution: 4K</span>
      </div>
    </div>
  );
};

