/**
 * Calculates Recurrence Plot matrix
 */
export const calculateRecurrence = (data: number[], threshold: number = 0.1): number[][] => {
  const n = data.length;
  if (n === 0) return [];

  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      const dist = Math.abs(data[i] - data[j]);
      row.push(dist < threshold ? 1 : 0);
    }
    matrix.push(row);
  }
  return matrix;
};

/**
 * Institutional Signal Helpers
 */
export const calculateZScore = (val: number, mean: number, std: number) => (val - mean) / std;

export const calculateKelly = (prob: number, winLossRatio: number) => {
  const q = 1 - prob;
  return (prob * winLossRatio - q) / winLossRatio;
};

export const generateSORData = (totalAmount: number) => {
  const splits = 8;
  const childOrders = [];
  let remaining = totalAmount;
  for (let i = 0; i < splits; i++) {
    const amount = i === splits - 1 ? remaining : (totalAmount / splits) * (0.8 + Math.random() * 0.4);
    childOrders.push({
      id: `ord-${i}`,
      venue: i % 2 === 0 ? 'Binance' : 'NQ Swap',
      amount,
      status: i < 3 ? 'FILLED' : i === 3 ? 'ACTIVE' : 'PENDING'
    });
    remaining -= amount;
  }
  return childOrders;
};

/**
 * Calculates Gramian Angular Field (GASF)
 * Provides spatial correlation analysis for time-series data
 */
export const calculateGAF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  // Normalize to [-1, 1]
  const min = Math.min(...data);
  const max = Math.max(...data);
  const norm = data.map(x => (2 * (x - min) / (max - min || 1)) - 1);
  // Transform to polar coordinates
  const phi = norm.map(x => Math.acos(x));
  const matrix: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      row.push(Math.cos(phi[i] + phi[j]));
    }
    matrix.push(row);
  }
  return matrix;
};

/**
 * Calculates Markov Transition Field (MTF)
 * Encodes dynamic transition probabilities into a matrix representation
 */
export const calculateMTF = (data: number[]): number[][] => {
  const n = data.length;
  if (n === 0) return [];
  const bins = 10;
  const min = Math.min(...data);
  const max = Math.max(...data);
  const step = (max - min || 1) / bins;
  const binned = data.map(x => Math.min(Math.floor((x - min) / step), bins - 1));
  const transitionMatrix = Array.from({ length: bins }, () => new Array(bins).fill(0));
  for (let i = 0; i < n - 1; i++) {
    transitionMatrix[binned[i]][binned[i + 1]]++;
  }
  for (let i = 0; i < bins; i++) {
    const sum = transitionMatrix[i].reduce((a, b) => a + b, 0);
    if (sum > 0) transitionMatrix[i] = transitionMatrix[i].map(x => x / sum);
  }
  const mtf: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      row.push(transitionMatrix[binned[i]][binned[j]]);
    }
    mtf.push(row);
  }
  return mtf;
};

/**
 * Generates Monte Carlo simulation paths for price prediction
 */
export const generateMonteCarloPaths = (startPrice: number, days: number = 30, numPaths: number = 50): number[][] => {
  const paths: number[][] = [];
  const volatility = 0.05;
  for (let i = 0; i < numPaths; i++) {
    const path = [startPrice];
    for (let j = 0; j < days; j++) {
      const last = path[path.length - 1];
      const change = last * (volatility * (Math.random() - 0.5));
      path.push(last + change);
    }
    paths.push(path);
  }
  return paths;
};

