 */
export const generateWalletGraph = (numNodes: number = 10) => {
  const nodes = Array.from({ length: numNodes }, (_, i) => ({
    id: `w-${i}`,
    type: (i === 0 ? 'CORE' : i % 5 === 0 ? 'SNIPER' : 'RETAIL') as 'CORE' | 'SNIPER' | 'RETAIL',
    val: 10 + Math.random() * 50
  }));
  const links = Array.from({ length: Math.floor(numNodes * 1.5) }, () => ({
    source: nodes[Math.floor(Math.random() * nodes.length)].id,
    target: nodes[Math.floor(Math.random() * nodes.length)].id,
    flowValue: Math.random() * 100
  }));
  return { nodes, links };
};

