                autoFocus
              />
              <button onClick={verifyAuth} className={`w-full py-8 ${isGov ? 'bg-amber-500' : 'bg-cyan-500'} text-black font-black uppercase tracking-[0.5em] rounded-[32px]`}>Verify</button>
            </div>
          </div>
        )}
      </div>
    );
