        <button onClick={() => setViewState(ViewState.LANDING)} className={`p-5 rounded-2xl mb-10 hover:scale-110 transition-transform ${isGov ? 'bg-amber-500' : 'bg-cyan-500'}`}>
          <ShieldAlert size={24} className="text-black" />
        </button>

        {!isGov ? (
          <>
            <button onClick={() => setViewState(ViewState.MARKET_SURFACE)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.MARKET_SURFACE ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <Grid size={24} />
            </button>
            <button onClick={() => setViewState(ViewState.TECHNICAL)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.TECHNICAL ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <BarChart3 size={24} />
            </button>
            <button onClick={() => setViewState(ViewState.DOCS)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.DOCS ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <FileText size={24} />
            </button>
