                    <h4 className="text-4xl font-black mb-2 tracking-tighter">{token.name}</h4>
                    <p className="text-xl font-black mono text-gray-500">{formatPrice(token.priceUsd)}</p>
                  </button>
                ))}
              </div>
            </div>
          )}

          {viewState === ViewState.TECHNICAL && currentToken && (
            <div className="grid grid-cols-12 gap-10 animate-fade-in">
              <div className="col-span-12 lg:col-span-8 space-y-10">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  <RetinaDisplay data={generateTechnicalData()} type="GAF" />
                  <div className={`rounded-[56px] p-10 h-[550px] border shadow-2xl overflow-hidden ${isDark ? 'bg-white/[0.02] border-white/5' : 'bg-white border-slate-200'}`}>
                    <LiquidityHeatmap 
                      bids={Array.from({length: 12}, (_, i) => ({ price: currentToken.priceUsd - i*0.012, size: Math.random() * 80 }))} 
                      asks={Array.from({length: 12}, (_, i) => ({ price: currentToken.priceUsd + i*0.012, size: Math.random() * 80 }))} 
                    />
                  </div>
                </div>
                <div className="h-[600px] w-full">
                  <WalletGraph data={walletData} />
                </div>
              </div>

              <div className="col-span-12 lg:col-span-4 space-y-8">
                {/* DIRECT ACTION COMMAND CARD */}
                <div className={`rounded-[56px] p-12 border-t-[16px] shadow-3xl min-h-[500px] flex flex-col ${isDark ? 'bg-[#0f0f12]' : 'bg-white'} ${report?.directive?.includes('BUY') ? 'border-emerald-500' : report?.directive === 'SELL' ? 'border-rose-500' : 'border-cyan-500'}`}>
                  <div className="flex items-center gap-4 mb-10">
                    <Zap size={24} className="text-cyan-500 animate-pulse" />
                    <h2 className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-500">Decision Hub v7.1</h2>
                  </div>

                  {report ? (
                    <div className="flex-1 flex flex-col">
                      <div className={`mb-10 px-8 py-4 rounded-3xl inline-block w-fit text-3xl font-black italic uppercase tracking-widest shadow-lg ${report.directive.includes('BUY') ? 'bg-emerald-500 text-black' : report.directive === 'SELL' ? 'bg-rose-500 text-white' : 'bg-gray-500 text-white'}`}>
                        {report.directive}
                      </div>
                      <h3 className="text-5xl font-black uppercase leading-none mb-6 tracking-tighter">{report.action_title}</h3>
                      <p className="text-xl italic text-gray-400 font-medium mb-10 leading-relaxed">
                        "{userMode === UserMode.RETAIL ? report.retail_reasoning : report.retina_interpretation}"
                      </p>

                      <div className="grid grid-cols-2 gap-6 mt-auto">
                        <div className="bg-white/5 p-6 rounded-3xl border border-white/5">
                           <span className="text-[10px] text-gray-600 font-black uppercase block mb-1">Alpha Tier</span>
                           <span className="text-2xl font-black text-cyan-400 mono">{report.roi_tier || 'SCALP'}</span>
                        </div>
                        <div className="bg-white/5 p-6 rounded-3xl border border-white/5">
                           <span className="text-[10px] text-gray-600 font-black uppercase block mb-1">Projected ROI</span>
                           <span className="text-2xl font-black text-emerald-500 mono">{report.projected_gain}%</span>
                        </div>
                      </div>
                      <button onClick={() => setIsExecutionModalOpen(true)} className="w-full py-8 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-[32px] mt-10 shadow-2xl hover:scale-105 transition-transform active:scale-95">Route to Node</button>
                    </div>
                  ) : (
                    <div className="flex-1 flex flex-col items-center justify-center text-center">
                       <RefreshCw size={64} className={`mb-8 text-gray-800 ${isAnalyzing ? 'animate-spin' : ''}`} />
                       <button 
                        onClick={async () => {
                          setIsAnalyzing(true);
                          const res = await getMEVAnalysis(userMode, { 
                            token: currentToken.name, 
                            price: currentToken.priceUsd,
                            marketCap: currentToken.marketCap,
                            strategy: userMode === UserMode.RETAIL ? 'SCALP' : 'INSTITUTIONAL_ARBITRAGE'
                          });
                          setReport(res);
                          setIsAnalyzing(false);
                        }}
                        className="w-full py-8 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-[32px] shadow-xl"
                      >
                        {isAnalyzing ? "Analyzing Matrix..." : "Sync Signal Directive"}
                      </button>
                    </div>
                  )}
                </div>

                <ProfitSimulator 
                  capital={10000} 
                  onCapitalChange={() => {}} 
                  report={report} 
                  currentPrice={currentToken.priceUsd} 
                  strategy={userMode} 
                />
              </div>
            </div>
          )}

          {viewState === ViewState.SENTINEL && <MarketSentinel lang={lang} theme={theme} />}

          {viewState === ViewState.DOCS && (
            <div className="max-w-4xl mx-auto py-20">
              <h2 className="text-7xl font-black uppercase italic mb-12">Protocol Dossier</h2>
              <div className="space-y-12">
                 <div className="p-12 bg-white/5 border border-white/5 rounded-[48px]">
                    <h4 className="text-2xl font-black uppercase text-cyan-400 mb-6">01 // Vision Spectrograms</h4>
                    <p className="text-xl text-gray-400 leading-relaxed">Neural training on Gramian Angular Fields allows the system to detect Wyckoff accumulation phases 12-24 hours before price action confirmation.</p>
                 </div>
                 <div className="p-12 bg-white/5 border border-white/5 rounded-[48px]">
                    <h4 className="text-2xl font-black uppercase text-violet-400 mb-6">02 // Jito Bundle Integration</h4>
                    <p className="text-xl text-gray-400 leading-relaxed">Direct routing via co-located validators ensures zero-slippage execution and front-run protection on all institutional directives.</p>
                 </div>
              </div>
            </div>
          )}
        </div>
      </main>

      <ExecutionModal isOpen={isExecutionModalOpen} onClose={() => setIsExecutionModalOpen(false)} token={currentToken} userMode={userMode} lang={lang} />
    </div>
  );
};

export default App;

