  ShieldAlert, Activity, Zap, Cpu, BarChart3, 
  User, Grid, X, Globe, Database, FileText, Sparkles, 
  Fingerprint, Terminal, Moon, Sun, Lock,
  RefreshCw, Eye, History, ShieldCheck, CheckCircle2,
  LockKeyhole, Building2, Search, TrendingUp, ArrowUpRight,
  Map as MapIcon, ChevronRight, Binary, Target, Box
} from 'lucide-react';
import { ViewState, UserMode, Language, Theme } from './types';
import { translations } from './translations';
import { 
  generateMempoolData, 
  generateTechnicalData, 
  calculateKelly, 
  calculateZScore, 
  generateSORData,
  generateWalletGraph 
} from './utils/math';
import { getMEVAnalysis } from './services/geminiService';
import { fetchTopMarkets, EnhancedTokenData, formatPrice, resolveTokenByContract } from './services/coingeckoService';
import ProfitSimulator from './components/ProfitSimulator';
import RetinaDisplay from './components/RetinaDisplay';
import LiquidityHeatmap from './components/LiquidityHeatmap';
import ExecutionModal from './components/ExecutionModal';
import MarketSentinel from './components/MarketSentinel';
import WalletGraph from './components/WalletGraph';

const App: React.FC = () => {
  const [viewState, setViewState] = useState<ViewState>(ViewState.LANDING);
  const [userMode, setUserMode] = useState<UserMode>(UserMode.RETAIL);
  const [lang, setLang] = useState<Language>(Language.EN);
  const [theme, setTheme] = useState<'DARK' | 'LIGHT'>('DARK');
  const [showAuth, setShowAuth] = useState(false);
  const [passkey, setPasskey] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const [marketSurface, setMarketSurface] = useState<EnhancedTokenData[]>([]);
  const [currentToken, setCurrentToken] = useState<EnhancedTokenData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<any>(null);
  const [sorOrders, setSorOrders] = useState<any[]>([]);
  const [isExecutionModalOpen, setIsExecutionModalOpen] = useState(false);
  const [retinaType, setRetinaType] = useState<'GAF' | 'MTF' | 'RECURRENCE'>('GAF');

  useEffect(() => {
    const init = async () => {
      const data = await fetchTopMarkets(50);
      setMarketSurface(data);
      if (data.length > 0) setCurrentToken(data[0]);
      setSorOrders(generateSORData(50000));
    };
    init();
  }, []);

  const handleEnter = (mode: UserMode) => {
    setUserMode(mode);
    setShowAuth(true);
  };

  const verifyAuth = () => {
    if (passkey === '0000') {
      if (userMode === UserMode.GOVERNMENT) {
        setViewState(ViewState.SENTINEL);
      } else {
        setViewState(ViewState.MARKET_SURFACE);
      }
      setShowAuth(false);
    } else {
      alert("Invalid Clearance Key.");
    }
  };

  const handleTokenSelect = (token: EnhancedTokenData) => {
    setCurrentToken(token);
    setReport(null);
    setViewState(ViewState.TECHNICAL);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;
    const resolved = await resolveTokenByContract(searchQuery);
    if (resolved) handleTokenSelect(resolved);
  };

  const runSignalFusion = async () => {
    if (!currentToken) return;
    setIsAnalyzing(true);
    try {
      const res = await getMEVAnalysis(userMode, { 
        token: currentToken.name, 
        price: currentToken.priceUsd,
        marketCap: currentToken.marketCap,
        strategy: userMode === UserMode.RETAIL ? 'SCALP' : 'INSTITUTIONAL_ARBITRAGE'
      });
      // Inject Pillar 3 & 4: Kelly & Z-Score
      res.kelly_f = (calculateKelly(res.probability_success || 0.65, 2.5) * 100).toFixed(2);
      res.z_score = calculateZScore(currentToken.priceUsd, currentToken.priceUsd * 0.98, currentToken.priceUsd * 0.05).toFixed(2);
      setReport(res);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const t = translations[lang];
  const isDark = theme === 'DARK';
  const isGov = userMode === UserMode.GOVERNMENT;

  if (viewState === ViewState.LANDING) {
    return (
      <div className={`h-screen w-full flex flex-col items-center justify-center relative overflow-hidden transition-colors duration-500 ${isDark ? 'bg-[#020204]' : 'bg-[#fcfcfd]'}`}>
        <div className="z-10 text-center max-w-6xl animate-fade-in">
          <div className="flex flex-col items-center gap-4 mb-12">
            <div className={`flex items-center gap-4 px-6 py-2 rounded-full border ${isDark ? 'bg-cyan-500/5 border-cyan-500/20 shadow-[0_0_15px_rgba(0,240,255,0.1)]' : 'bg-blue-50 border-blue-100'}`}>
               <Sparkles size={14} className="text-cyan-500 animate-pulse" />
               <span className={`font-black text-[11px] uppercase tracking-[0.4em] mono ${isDark ? 'text-cyan-400' : 'text-blue-600'}`}>Sovereign Entity Powered</span>
            </div>
          </div>
          <h1 className={`text-9xl md:text-[11rem] font-black mb-10 tracking-tighter leading-none italic uppercase ${isDark ? 'text-white' : 'text-slate-950'}`}>
            DeFi<span className="text-cyan-400">Scope</span>
          </h1>
          <p className={`text-2xl md:text-3xl font-medium mb-24 tracking-tight ${isDark ? 'text-gray-500' : 'text-slate-400'}`}>{t.hero_sub}</p>

          <div className="flex flex-col md:flex-row gap-6 justify-center items-center">
            <button onClick={() => handleEnter(UserMode.RETAIL)} className="w-full md:w-auto px-12 py-6 bg-cyan-500 text-black font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs shadow-xl">Retail Hub</button>
            <button onClick={() => handleEnter(UserMode.INSTITUTIONAL)} className={`w-full md:w-auto px-12 py-6 border-2 font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs ${isDark ? 'border-cyan-500/50 text-cyan-400 shadow-[0_0_15px_rgba(0,240,255,0.1)]' : 'border-slate-300 text-slate-800'}`}>Institutional Portal</button>
            <button onClick={() => handleEnter(UserMode.GOVERNMENT)} className="w-full md:w-auto px-12 py-6 bg-amber-500 text-black font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs shadow-lg">Sovereign Watch</button>
          </div>
        </div>

        {showAuth && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center bg-black/95 backdrop-blur-2xl p-8">
            <div className={`w-full max-w-xl p-16 rounded-[64px] border shadow-2xl animate-pop-in ${isDark ? 'bg-[#0a0a0c] border-white/10' : 'bg-white border-slate-200'}`}>
              <h2 className="text-4xl font-black text-center uppercase tracking-widest mb-10">{userMode} Authentication</h2>
              <input 
                type="password"
                value={passkey}
                onChange={(e) => setPasskey(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && verifyAuth()}
                placeholder="Neural Passkey (0000)..."
                className={`w-full border rounded-[32px] p-8 text-xl mono mb-8 outline-none text-center tracking-[1em] ${isDark ? 'bg-white/5 border-white/10 text-white' : 'bg-slate-100 border-slate-200'}`}
