            <button onClick={() => handleEnter(UserMode.GOVERNMENT)} className="w-full md:w-auto px-12 py-6 bg-amber-500 text-black font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs shadow-lg">Sovereign Watch</button>
          </div>
        </div>

        {showAuth && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center bg-black/95 backdrop-blur-2xl p-8">
            <div className={`w-full max-w-xl p-16 rounded-[64px] border shadow-2xl animate-pop-in ${isDark ? 'bg-[#0a0a0c] border-white/10' : 'bg-white border-slate-200'}`}>
              <h2 className="text-4xl font-black text-center uppercase tracking-widest mb-10">{userMode} Authentication</h2>
              <input 
                type="password"
                value={passkey}
                onChange={(e) => setPasskey(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && verifyAuth()}
                placeholder="Neural Passkey (0000)..."
                className={`w-full border rounded-[32px] p-8 text-xl mono mb-8 outline-none text-center tracking-[1em] ${isDark ? 'bg-white/5 border-white/10 text-white' : 'bg-slate-100 border-slate-200'}`}
                autoFocus
              />
              <button onClick={verifyAuth} className={`w-full py-8 ${isGov ? 'bg-amber-500' : 'bg-cyan-500'} text-black font-black uppercase tracking-[0.5em] rounded-[32px]`}>Verify</button>
            </div>
          </div>
        )}
      </div>
    );
  }

