import React, { useState, useEffect } from 'react';
import { 
  ShieldAlert, Activity, Zap, Globe, Search, Cpu, RefreshCw, Target, 
  TrendingUp, Share2, Box, BarChart3, 
  Waves, Filter, Wallet, ArrowUpRight, ArrowDownRight, Rocket,
  Link as LinkIcon, Layers, ShieldCheck, WifiOff, ShoppingCart, 
  Binary, Grid, LayoutDashboard, Briefcase, User, Info, AlertCircle, Eye, ChevronRight, X, Map, Sparkles
} from 'lucide-react';
import { ViewState, UserMode } from './types';
import { generateMempoolData, generateTopographyData, generateWalletGraph, generateMetricChartData, generateTechnicalData, calculateKelly, calculateZScore, generateSORData } from './utils/math';
import { getMEVAnalysis } from './services/geminiService';
import { fetchTokenByAddress, fetchTopMarkets, EnhancedTokenData } from './services/coingeckoService';
import ProfitSimulator from './components/ProfitSimulator';
import RetinaDisplay from './components/RetinaDisplay';
import WalletGraph from './components/WalletGraph';
import LiquidityHeatmap from './components/LiquidityHeatmap';
import MarketSentinel from './components/MarketSentinel';
import ExecutionModal from './components/ExecutionModal';
import { translations } from './translations';

const App: React.FC = () => {
  const [viewState, setViewState] = useState<ViewState>(ViewState.LANDING);
  const [userMode, setUserMode] = useState<UserMode>(UserMode.RETAIL);
  const [lang] = useState<string>('EN');
  const [theme] = useState<'DARK' | 'LIGHT'>('DARK');
  const [searchQuery, setSearchQuery] = useState('');

  const [marketSurface, setMarketSurface] = useState<EnhancedTokenData[]>([]);
  const [currentToken, setCurrentToken] = useState<EnhancedTokenData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<any>(null);
  const [sorOrders, setSorOrders] = useState<any[]>([]);
  const [isExecutionModalOpen, setIsExecutionModalOpen] = useState(false);
  const [retinaType, setRetinaType] = useState<'GAF' | 'MTF' | 'RECURRENCE'>('GAF');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const init = async () => {
      const data = await fetchTopMarkets(50);
      setMarketSurface(data);
      if (data.length > 0) setCurrentToken(data[0] as EnhancedTokenData);
      setSorOrders(generateSORData(50000));
    };
    init();
  }, []);

  const handleEnter = (mode: UserMode) => {
    setUserMode(mode);
    if (mode === UserMode.GOVERNMENT) {
      setViewState(ViewState.SENTINEL);
    } else if (mode === UserMode.INSTITUTIONAL) {
      setViewState(ViewState.TECHNICAL);
    } else {
      setViewState(ViewState.MARKET_SURFACE);
    }
  };

  const handleTokenSelect = (token: EnhancedTokenData) => {
    setCurrentToken(token);
    setReport(null);
    setViewState(ViewState.TECHNICAL);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;
    const resolved = await fetchTokenByAddress(searchQuery);
    if (resolved) handleTokenSelect(resolved);
  };

  const runSignalFusion = async () => {
    if (!currentToken) return;
    setIsAnalyzing(true);
    try {
      const res = await getMEVAnalysis(userMode, { 
        token: currentToken.name, 
        price: currentToken.priceUsd,
        marketCap: currentToken.marketCap,
        strategy: userMode === UserMode.RETAIL ? 'SCALP' : 'INSTITUTIONAL_ARBITRAGE',
        technicals: generateTechnicalData(currentToken.priceUsd)
      });

      const prob = res.probability_success ?? 0.65;
      res.kelly_f = (calculateKelly(prob, 2.5) * 100).toFixed(2);
      res.z_score = calculateZScore(currentToken.priceUsd, currentToken.priceUsd * 0.98, currentToken.priceUsd * 0.05).toFixed(2);
      setReport(res);
    } catch (e) {
      console.error(e);
      setError("Neural Fusion Core failure. Retrying handshake...");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const formatPrice = (price: number | null | undefined) => {
    if (price === null || price === undefined || isNaN(price)) return '$0.00';
    if (price < 1) return `$${price.toFixed(8)}`;
    return `$${price.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const isDark = theme === 'DARK';
  const isGov = userMode === UserMode.GOVERNMENT;

  if (viewState === ViewState.LANDING) {
    return (
      <div className={`h-screen w-full flex flex-col items-center justify-center relative overflow-hidden transition-colors duration-500 ${isDark ? 'bg-[#020204]' : 'bg-[#fcfcfd]'}`}>
        <div className="z-10 text-center max-w-6xl animate-fade-in">
          <div className="flex flex-col items-center gap-4 mb-12">
            <div className={`flex items-center gap-4 px-6 py-2 rounded-full border ${isDark ? 'bg-cyan-500/5 border-cyan-500/20 shadow-[0_0_15px_rgba(0,240,255,0.1)]' : 'bg-blue-50 border-blue-100'}`}>
               <Sparkles size={14} className="text-cyan-500 animate-pulse" />
               <span className={`font-black text-[11px] uppercase tracking-[0.4em] mono ${isDark ? 'text-cyan-400' : 'text-blue-600'}`}>Sovereign Entity Powered</span>
            </div>
          </div>
          <h1 className={`text-9xl md:text-[11rem] font-black mb-10 tracking-tighter leading-none italic uppercase ${isDark ? 'text-white' : 'text-slate-950'}`}>
            DeFi<span className="text-cyan-400">Scope</span>
          </h1>
          <p className={`text-2xl md:text-3xl font-medium mb-24 tracking-tight ${isDark ? 'text-gray-500' : 'text-slate-400'}`}>Professional-grade on-chain visual intelligence.</p>

          <div className="flex flex-col md:flex-row gap-6 justify-center items-center">
            <button onClick={() => handleEnter(UserMode.RETAIL)} className="w-full md:w-auto px-12 py-6 bg-cyan-500 text-black font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs shadow-xl">Retail Hub</button>
            <button onClick={() => handleEnter(UserMode.INSTITUTIONAL)} className={`w-full md:w-auto px-12 py-6 border-2 font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs ${isDark ? 'border-cyan-500/50 text-cyan-400 shadow-[0_0_15px_rgba(0,240,255,0.1)]' : 'border-slate-300 text-slate-800'}`}>Institutional Portal</button>
            <button onClick={() => handleEnter(UserMode.GOVERNMENT)} className="w-full md:w-auto px-12 py-6 bg-amber-500 text-black font-black uppercase tracking-[0.2em] rounded-[24px] hover:scale-105 transition-all text-xs shadow-lg">Sovereign Watch</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className={`h-screen flex overflow-hidden transition-all duration-700 ${isDark ? 'bg-[#020204] text-white' : 'bg-[#f8f9fa] text-slate-900'}`}>

      <nav className={`w-24 border-r flex flex-col items-center py-10 gap-10 z-[150] shrink-0 ${isDark ? 'bg-[#08080c] border-white/5' : 'bg-white border-slate-200 shadow-xl'}`}>
        <button onClick={() => setViewState(ViewState.LANDING)} className={`p-5 rounded-2xl mb-10 hover:scale-110 transition-transform ${isGov ? 'bg-amber-500' : 'bg-cyan-500'} shadow-[0_0_15px_rgba(0,240,255,0.4)]`}>
          <Eye size={24} className="text-black" />
        </button>

        {!isGov ? (
          <>
            <button onClick={() => setViewState(ViewState.MARKET_SURFACE)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.MARKET_SURFACE ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <Grid size={24} />
            </button>
            <button onClick={() => setViewState(ViewState.TECHNICAL)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.TECHNICAL ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <BarChart3 size={24} />
            </button>
            <button onClick={() => setViewState(ViewState.GRAPH)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.GRAPH ? 'bg-cyan-500/10 text-cyan-400' : 'text-gray-500 hover:text-cyan-400'}`}>
              <Map size={24} />
            </button>
          </>
        ) : (
          <button onClick={() => setViewState(ViewState.SENTINEL)} className={`p-4 rounded-xl transition-all ${viewState === ViewState.SENTINEL ? 'bg-amber-500/10 text-amber-500' : 'text-gray-500 hover:text-amber-500'}`}>
            <ShieldCheck size={24} />
          </button>
        )}
      </nav>

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        {!isGov && (
          <header className={`h-24 border-b flex items-center px-12 justify-between shrink-0 ${isDark ? 'bg-[#08080c]/80 border-white/5' : 'bg-white/80 border-slate-200'} backdrop-blur-3xl`}>
            <form onSubmit={handleSearch} className="flex-1 max-w-xl relative">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
              <input 
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Resolve Contract Address..."
                className={`w-full py-4 pl-16 pr-6 rounded-full text-xs font-black mono outline-none border transition-all ${isDark ? 'bg-white/5 border-white/10 text-white focus:border-cyan-500' : 'bg-slate-50 border-slate-200 focus:border-cyan-500'}`}
              />
            </form>
            {currentToken && (
              <div className="flex items-center gap-8 ml-10">
                <div className="text-right">
                  <span className="text-[10px] font-black text-gray-500 uppercase block leading-none mb-1 tracking-widest">Network Live</span>
                  <span className={`text-2xl font-black italic mono ${isDark ? 'text-white' : 'text-slate-900'}`}>{formatPrice(currentToken.priceUsd)}</span>
                </div>
                <img src={currentToken.image} className="w-12 h-12 rounded-2xl shadow-xl" />
              </div>
            )}
          </header>
        )}

        <div className={`flex-1 overflow-y-auto scrollbar-hide ${isGov ? '' : 'p-12'}`}>
          {viewState === ViewState.MARKET_SURFACE && (
            <div className="animate-fade-in space-y-16">
              <h2 className="text-7xl font-black italic uppercase tracking-tighter">Market Surface</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {marketSurface.map(token => (
                  <button key={token.id} onClick={() => handleTokenSelect(token)} className={`p-10 rounded-[56px] border transition-all text-left group hover:scale-[1.05] shadow-xl ${isDark ? 'bg-white/[0.02] border-white/5 hover:border-cyan-500/40' : 'bg-white border-slate-200'}`}>
                    <div className="flex justify-between items-start mb-8">
                      <img src={token.image} className="w-16 h-16 rounded-2xl shadow-lg group-hover:rotate-12 transition-transform" />
                      <span className={`text-sm font-black mono px-4 py-2 rounded-full ${(token.priceChange24h ?? 0) >= 0 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                        {(token.priceChange24h ?? 0).toFixed(2)}%
                      </span>
                    </div>
                    <h4 className="text-4xl font-black mb-2 tracking-tighter">{token.name}</h4>
                    <p className="text-xl font-black mono text-gray-500">{formatPrice(token.priceUsd)}</p>
                  </button>
                ))}
              </div>
            </div>
          )}

          {viewState === ViewState.TECHNICAL && currentToken && (
            <div className="grid grid-cols-12 gap-10 animate-fade-in max-w-[1700px] mx-auto">
              <div className="col-span-12 lg:col-span-8 space-y-10">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <RetinaDisplay data={generateMetricChartData(currentToken.priceUsd)} type={retinaType} />
                    <div className="flex gap-4">
                      {(['GAF', 'MTF', 'RECURRENCE'] as const).map(t => (
                        <button key={t} onClick={() => setRetinaType(t as any)} className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${retinaType === t ? 'bg-cyan-500 border-cyan-500 text-black' : 'border-white/10 hover:border-cyan-500/50 text-gray-500'}`}>{t}</button>
                      ))}
                    </div>
                  </div>
                  <div className={`rounded-[56px] p-10 h-[550px] border shadow-2xl overflow-hidden ${isDark ? 'bg-white/[0.02] border-white/5' : 'bg-white border-slate-200'}`}>
                    <LiquidityHeatmap 
                      bids={Array.from({length: 12}, (_, i) => ({ price: (currentToken.priceUsd ?? 0) - i*0.012, size: Math.random() * 80, isAnomalous: Math.random() > 0.9 }))} 
                      asks={Array.from({length: 12}, (_, i) => ({ price: (currentToken.priceUsd ?? 0) + i*0.012, size: Math.random() * 80, isAnomalous: Math.random() > 0.9 }))} 
                    />
                  </div>
                </div>

                <div className={`rounded-[56px] p-12 border border-white/5 bg-[#08080c] shadow-2xl h-[500px] overflow-hidden flex flex-col`}>
                   <div className="flex justify-between items-center mb-10">
                      <div>
                        <h3 className="text-xs font-black uppercase tracking-[0.4em] text-cyan-500 mb-2">Smart Order Routing (SOR)</h3>
                        <p className="text-[10px] mono text-gray-500">Visualizing Parent-to-Child order splits for sub-ms execution.</p>
                      </div>
                      <span className="px-4 py-1.5 bg-emerald-500/10 text-emerald-500 rounded-full text-[10px] font-black mono animate-pulse">OPTIMIZED</span>
                   </div>
                   <div className="flex-1 space-y-4 overflow-y-auto">
                      {sorOrders.map((o, i) => (
                        <div key={i} className="flex items-center justify-between p-5 bg-white/5 border border-white/5 rounded-3xl hover:bg-white/10 transition-all">
                           <div className="flex items-center gap-6">
                              <div className={`w-2 h-2 rounded-full ${o.status === 'FILLED' ? 'bg-emerald-500' : 'bg-cyan-500 animate-pulse shadow-[0_0_10px_cyan]'}`} />
                              <span className="text-xs font-bold text-white mono">{o.id}</span>
                              <span className="text-[10px] text-gray-600 mono">{o.venue}</span>
                           </div>
                           <div className="flex items-center gap-10">
                              <span className="text-xs font-black text-cyan-400 mono">${o.amount.toLocaleString()}</span>
                              <div className={`px-4 py-1 rounded-full text-[9px] font-black ${o.status === 'FILLED' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-white/10 text-gray-500'}`}>{o.status}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              </div>

              <div className="col-span-12 lg:col-span-4 space-y-8">
                <div className={`rounded-[56px] p-12 border-t-[16px] shadow-3xl min-h-[500px] flex flex-col ${isDark ? 'bg-[#0f0f12]' : 'bg-white'} ${report?.directive?.includes('BUY') ? 'border-emerald-500' : report?.directive === 'SELL' ? 'border-rose-500' : 'border-cyan-500'}`}>
                  <div className="flex items-center gap-4 mb-10">
                    <Zap size={24} className="text-cyan-500 animate-pulse" />
                    <h2 className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-500 italic">Decision Hub v1.0.4</h2>
                  </div>

                  {report ? (
                    <div className="flex-1 flex flex-col animate-fade-in">
                      <div className={`mb-10 px-8 py-4 rounded-3xl inline-block w-fit text-3xl font-black italic uppercase tracking-widest shadow-lg ${report.directive.includes('BUY') ? 'bg-emerald-500 text-black shadow-[0_0_20px_rgba(16,185,129,0.3)]' : report.directive === 'SELL' ? 'bg-rose-500 text-white' : 'bg-gray-500 text-white'}`}>
                        {report.directive}
                      </div>
                      <h3 className="text-5xl font-black uppercase leading-none mb-6 tracking-tighter">{report.action_title}</h3>
                      <p className="text-xl italic text-gray-400 font-medium mb-10 leading-relaxed">
                        "{userMode === UserMode.RETAIL ? report.retail_reasoning : report.retina_interpretation}"
                      </p>

                      <div className="grid grid-cols-2 gap-6 mt-auto">
                        <div className="bg-white/5 p-6 rounded-3xl border border-white/5">
                           <span className="text-[10px] text-gray-600 font-black uppercase block mb-1">Kelly Criterion (F*)</span>
                           <span className="text-2xl font-black text-cyan-400 mono">{report.kelly_f}%</span>
                        </div>
                        <div className="bg-white/5 p-6 rounded-3xl border border-white/5">
                           <span className="text-[10px] text-gray-600 font-black uppercase block mb-1">Z-Score Alpha</span>
                           <span className="text-2xl font-black text-violet-400 mono">{report.z_score}</span>
                        </div>
                      </div>
                      <button onClick={() => setIsExecutionModalOpen(true)} className="w-full py-8 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-[32px] mt-10 shadow-2xl hover:scale-105 transition-transform">Execute Signal</button>
                    </div>
                  ) : (
                    <div className="flex-1 flex flex-col items-center justify-center text-center py-20">
                       <RefreshCw size={64} className={`mb-8 text-gray-800 ${isAnalyzing ? 'animate-spin' : ''}`} />
                       <button 
                        onClick={runSignalFusion}
                        disabled={isAnalyzing}
                        className="w-full py-8 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-[32px] shadow-xl hover:scale-105 transition-all disabled:opacity-50"
                      >
                        {isAnalyzing ? "Synthesizing Fusion..." : "Run Signal Fusion"}
                      </button>
                    </div>
                  )}
                </div>

                <ProfitSimulator 
                  capital={10000} 
                  onCapitalChange={() => {}} 
                  report={report} 
                  currentPrice={currentToken.priceUsd} 
                  strategy={userMode} 
                />
              </div>
            </div>
          )}

          {viewState === ViewState.GRAPH && <div className="h-[800px] bg-black/40 rounded-[64px] border border-white/5"><WalletGraph data={generateWalletGraph()} /></div>}

          {viewState === ViewState.SENTINEL && <MarketSentinel lang={lang} theme={theme} />}
        </div>
      </main>

      {error && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-600 text-white px-10 py-5 rounded-[32px] shadow-2xl flex items-center gap-6 z-[200] animate-bounce">
          <AlertCircle size={24} />
          <span className="text-xs font-black uppercase tracking-widest">{error}</span>
          <button onClick={() => setError(null)}><X size={20}/></button>
        </div>
      )}

      <ExecutionModal 
        isOpen={isExecutionModalOpen} 
        onClose={() => setIsExecutionModalOpen(false)} 
        token={currentToken} 
        userMode={userMode} 
        lang={lang} 
      />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Zap, AlertTriangle, Box, Layers, Activity } from 'lucide-react';

interface MempoolTx {
  id: string;
  gasPrice: number;
  value: number;
  time: number;
  type: string;
  isMEV: boolean;
}

interface MempoolVisualizerProps {
  data: MempoolTx[];
}

const StatCard = ({ label, value, sub, icon, color }: any) => (
  <div className="bg-[#0a0a0a] border border-white/5 p-5 rounded-2xl flex flex-col gap-1 group hover:border-white/10 transition-colors">
     <div className="flex justify-between items-start mb-2">
        <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest">{label}</span>
        <div className={`p-1.5 rounded-lg bg-white/5 ${color}`}>{icon}</div>
     </div>
     <div className="text-xl font-black text-white uppercase tracking-tight">{value}</div>
     <div className={`text-[9px] font-bold ${color} opacity-80`}>{sub}</div>
  </div>
);

const MempoolVisualizer: React.FC<MempoolVisualizerProps> = ({ data }) => {
  // Stats
  const avgGas = useMemo(() => data.reduce((acc, tx) => acc + tx.gasPrice, 0) / (data.length || 1), [data]);
  const mevCount = useMemo(() => data.filter(tx => tx.isMEV).length, [data]);
  const totalValue = useMemo(() => data.reduce((acc, tx) => acc + tx.value, 0), [data]);

  return (
    <div className="h-full flex flex-col gap-6">
      {/* Header Stats */}
      <div className="grid grid-cols-4 gap-4">
        <StatCard label="Network Congestion" value={`${(avgGas).toFixed(1)} Gwei`} sub="Base Fee + Priority" icon={<Activity size={16}/>} color="text-yellow-400" />
        <StatCard label="MEV Threat Level" value={mevCount > 5 ? 'CRITICAL' : 'MODERATE'} sub={`${mevCount} Bot Tx Detected`} icon={<AlertTriangle size={16}/>} color={mevCount > 5 ? "text-red-500" : "text-orange-400"} />
        <StatCard label="Pending Liquidity" value={`$${(totalValue * 2800).toLocaleString(undefined, { maximumFractionDigits: 0 })}`} sub="Est. Block Value" icon={<Box size={16}/>} color="text-blue-400" />
        <StatCard label="Block Utilization" value="84%" sub="Target: 50%" icon={<Layers size={16}/>} color="text-green-400" />
      </div>

      {/* Main Feed */}
      <div className="flex-1 bg-[#0a0a0a] rounded-[32px] border border-white/5 overflow-hidden flex flex-col shadow-2xl relative h-[500px]">
         <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-yellow-500/50 to-transparent z-20" />

         <div className="p-6 border-b border-white/5 bg-black/40 flex justify-between items-center z-10">
            <h2 className="text-[11px] font-black uppercase tracking-[0.2em] flex items-center gap-3 text-yellow-500">
               <Zap size={16}/> Live Mempool Stream (Geth Node)
            </h2>
            <div className="flex items-center gap-4">
               <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Scanning Block #{18429100 + Math.floor(Date.now() / 12000)}</span>
            </div>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
            <div className="grid grid-cols-12 px-4 py-2 text-[8px] font-black text-gray-600 uppercase tracking-widest border-b border-white/5 sticky top-0 bg-[#0a0a0a] z-10">
               <div className="col-span-2">Tx Hash</div>
               <div className="col-span-1">Method</div>
               <div className="col-span-2 text-right">Value (ETH)</div>
               <div className="col-span-2 text-right">Gas Price</div>
               <div className="col-span-3 text-center">Threat Assessment</div>
               <div className="col-span-2 text-right">Time</div>
            </div>
            {data.map((tx, idx) => (
               <div key={tx.id} className={`grid grid-cols-12 items-center px-4 py-3 rounded-xl border border-transparent transition-all hover:bg-white/5 ${tx.isMEV ? 'bg-red-500/5 border-red-500/10' : ''}`}>
                  <div className="col-span-2 flex items-center gap-2">
                     <div className={`w-1.5 h-1.5 rounded-full ${tx.isMEV ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`} />
                     <span className="text-[10px] mono text-gray-400">0x{Math.random().toString(16).slice(2,8)}...</span>
                  </div>
                  <div className="col-span-1">
                     <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded uppercase ${tx.type === 'swap' ? 'bg-blue-500/10 text-blue-400' : 'bg-gray-800 text-gray-400'}`}>
                        {tx.type}
                     </span>
                  </div>
                  <div className="col-span-2 text-right text-[10px] mono text-white">
                     {tx.value.toFixed(4)}
                  </div>
                  <div className="col-span-2 text-right text-[10px] mono text-yellow-500">
                     {tx.gasPrice.toFixed(1)} <span className="text-gray-600">gwei</span>
                  </div>
                  <div className="col-span-3 flex justify-center">
                     {tx.isMEV ? (
                        <div className="flex items-center gap-1 text-red-500 bg-red-500/10 px-2 py-0.5 rounded border border-red-500/20">
                           <AlertTriangle size={10} />
                           <span className="text-[8px] font-black uppercase">Sandwich</span>
                        </div>
                     ) : (
                        <span className="text-[8px] text-gray-700 font-bold uppercase">Safe</span>
                     )}
                  </div>
                  <div className="col-span-2 text-right text-[9px] mono text-gray-500">
                     -{idx * 100}ms
                  </div>
               </div>
            ))}
         </div>
      </div>
    </div>
  );
};

export default MempoolVisualizer;

import React, { useState, useEffect, useRef } from 'react';
import { 
  ShieldAlert, Activity, Zap, Search, Cpu, RefreshCw, 
  TrendingUp, Map as MapIcon, Share2, BarChart3, 
  Waves, Briefcase, User, Info, AlertCircle, ShoppingCart, 
  Binary, Grid, Layers, Rocket, Target, ChevronRight, X,
  Network, ArrowRightLeft, MousePointer2, Globe, Database, ListFilter,
  ArrowUpRight, ArrowDownRight, Eye, Hash, Server, Clock, ShieldCheck,
  Languages, Lock, Key, CheckCircle
} from 'lucide-react';
import { ViewState, UserMode, TokenData, IntelligenceMetric, EntityTransfer, Language } from './types';
import { translations } from './translations';
import { generateMempoolData, generateWalletGraph, generateTechnicalData } from './utils/math';
import { getMEVAnalysis } from './services/geminiService';
import { fetchTokenByAddress, fetchTopMarkets, EnhancedTokenData } from './services/coingeckoService';
import ProfitSimulator from './components/ProfitSimulator';
import RetinaDisplay from './components/RetinaDisplay';
import WalletGraph from './components/WalletGraph';
import LiquidityHeatmap from './components/LiquidityHeatmap';
import ExecutionModal from './components/ExecutionModal';
import MempoolVisualizer from './components/MempoolVisualizer';

const INSTITUTIONS = [
  'Wintermute', 'Jump Crypto', 'Amber Group', 'Cumberland', 
  'FalconX', 'Genesis Trading', 'Galaxy Digital', 'Paradigm', 
  'Dragonfly Capital', 'Flow Traders'
];

const TRANSFER_TYPES = [
  'Liquidity Injection', 'Treasury Rebalance', 'OTC Settlement', 
  'LP Extraction', 'Staking Deposit', 'Governance Voting'
];

const RETAIL_ALPHA_SOURCES = [
  'X (Twitter) Trending', 'Telegram Whale Pulse', 'DexTools Hot #1', 
  'Sentiment Spike', 'New LP Added', 'Social Volume Hub'
];

const App: React.FC = () => {
  const [userMode, setUserMode] = useState<UserMode>(UserMode.RETAIL);
  const [lang, setLang] = useState<Language>(Language.EN);
  const [activeView, setActiveView] = useState<ViewState>(ViewState.MARKET_SURFACE);
  const [marketSurface, setMarketSurface] = useState<TokenData[]>([]);
  const [currentToken, setCurrentToken] = useState<EnhancedTokenData | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<any>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [techData, setTechData] = useState<any>(null);
  const [mempool, setMempool] = useState<any[]>([]);
  const [walletData, setWalletData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [transfers, setTransfers] = useState<EntityTransfer[]>([]);
  const [selectedTransfer, setSelectedTransfer] = useState<any>(null);
  const [capital, setCapital] = useState(5000);

  // Gating State
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [authKey, setAuthKey] = useState('');
  const [isGated, setIsGated] = useState(false);

  // Execution State
  const [isExecutionModalOpen, setIsExecutionModalOpen] = useState(false);

  const t = translations[lang];

  // Sync capital to mode constraints
  useEffect(() => {
    if (userMode === UserMode.INSTITUTIONAL) {
      if (capital < 500000) setCapital(500000);
    } else {
      if (capital > 500000) setCapital(500000);
    }
  }, [userMode]);

  // Auto-scan Top 500
  useEffect(() => {
    const scan = async () => {
      const data = await fetchTopMarkets();
      setMarketSurface(data);
      if (userMode === UserMode.INSTITUTIONAL && !currentToken) {
        handleTokenSelect(data[0]);
      }
    };
    scan();
  }, [userMode]);

  useEffect(() => {
    const interval = setInterval(() => {
      setMempool(generateMempoolData(35));

      if (currentToken) {
        if (userMode === UserMode.INSTITUTIONAL) {
          // Institutional Feed
          const entity = INSTITUTIONS[Math.floor(Math.random() * INSTITUTIONS.length)];
          const type = TRANSFER_TYPES[Math.floor(Math.random() * TRANSFER_TYPES.length)];
          const newTransfer: EntityTransfer = {
            id: Math.random().toString(),
            from: `${entity}: Institutional Node`,
            to: 'Binance: Hot Wallet 04',
            amount: Math.random() * 500000,
            symbol: currentToken.symbol,
            time: new Date().toLocaleTimeString(),
            entity: entity,
            type: type,
            hash: '0x' + Math.random().toString(16).slice(2, 42),
            gas: (Math.random() * 100).toFixed(2) + ' Gwei'
          };
          setTransfers(prev => [newTransfer, ...prev].slice(0, 8));
        } else {
          // Retail Alpha Feed
          const source = RETAIL_ALPHA_SOURCES[Math.floor(Math.random() * RETAIL_ALPHA_SOURCES.length)];
          const sentiment = Math.random() > 0.5 ? 'BULLISH' : 'NEUTRAL';
          const newTransfer: EntityTransfer = {
            id: Math.random().toString(),
            from: source,
            to: 'Retail Trend Monitor',
            amount: Math.random() * 20000,
            symbol: currentToken.symbol,
            time: new Date().toLocaleTimeString(),
            entity: source,
            type: 'Social Pulse',
            sentiment: sentiment as any,
            hash: 'N/A - Off-chain Signal',
            gas: 'N/A'
          };
          setTransfers(prev => [newTransfer, ...prev].slice(0, 8));
        }
      }
    }, 4500);
    return () => clearInterval(interval);
  }, [currentToken, userMode]);

  useEffect(() => {
    if (currentToken) {
      setWalletData(generateWalletGraph(currentToken.symbol, userMode));
    }
  }, [currentToken, userMode]);

  const handleTokenSelect = (token: TokenData) => {
    setCurrentToken(token as EnhancedTokenData);
    setTechData(generateTechnicalData(token.priceUsd));
    setReport(null);
    if (userMode === UserMode.INSTITUTIONAL && activeView === ViewState.MARKET_SURFACE) {
      setActiveView(ViewState.TECHNICAL);
    }
  };

  const trySwitchMode = (mode: UserMode) => {
    if (mode === UserMode.INSTITUTIONAL && !isGated) {
      setShowAuthModal(true);
    } else {
      setUserMode(mode);
      setTransfers([]); // Clear feed to swap sources
    }
  };

  const handleVerify = () => {
    if (authKey.length >= 4) {
      setIsGated(true);
      setUserMode(UserMode.INSTITUTIONAL);
      setShowAuthModal(false);
      setTransfers([]);
    } else {
      setError("Invalid Access Token");
    }
  };

  const runAnalysis = async () => {
    if (!currentToken) return;
    setIsAnalyzing(true);
    try {
      const res = await getMEVAnalysis(userMode, {
        token: currentToken.name,
        price: currentToken.priceUsd,
        marketCap: currentToken.marketCap,
        strategy: 'QUANT',
        technicals: techData
      });
      setReport(res);
    } catch (e) {
      setError("Prediction Engine Timeout.");
    }
    setIsAnalyzing(false);
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery) return;

    setIsSearching(true);
    setError(null);

    try {
      const data = await fetchTokenByAddress(searchQuery);
      if (data) {
        handleTokenSelect(data);
        setSearchQuery('');
      } else {
        setError("Meta-Search found no matches. Check address/chain.");
      }
    } catch (err) {
      setError("Deep search protocol failed.");
    } finally {
      setIsSearching(false);
    }
  };

  const formatPrice = (p: number | undefined | null) => {
    if (p === undefined || p === null || isNaN(p)) return '---';
    return p < 1 ? p.toFixed(8) : p.toLocaleString(undefined, { maximumFractionDigits: 4 });
  };

  return (
    <div className={`min-h-screen ${userMode === UserMode.INSTITUTIONAL ? 'bg-[#050505]' : 'bg-[#080808]'} text-white flex flex-col lg:flex-row overflow-hidden font-sans transition-colors duration-1000`}>

      {/* MODE CONTROLLER SIDEBAR */}
      <nav className="w-full lg:w-24 border-r border-white/5 bg-black/40 backdrop-blur-xl flex lg:flex-col items-center py-10 gap-8 z-50">
        <div className={`p-4 rounded-2xl ${userMode === UserMode.INSTITUTIONAL ? 'bg-blue-600 shadow-[0_0_30px_rgba(37,99,235,0.4)]' : 'bg-red-600 shadow-[0_0_30px_rgba(220,38,38,0.4)]'} transition-all duration-700`}>
          <ShieldAlert size={32} />
        </div>

        <div className="flex lg:flex-col gap-6">
          <button 
            onClick={() => trySwitchMode(UserMode.INSTITUTIONAL)}
            className={`p-4 rounded-xl transition-all ${userMode === UserMode.INSTITUTIONAL ? 'bg-blue-600/20 text-blue-500' : 'text-gray-600 hover:text-white'}`}
            title="Institutional"
          >
            <Briefcase size={24} />
          </button>
          <button 
            onClick={() => trySwitchMode(UserMode.RETAIL)}
            className={`p-4 rounded-xl transition-all ${userMode === UserMode.RETAIL ? 'bg-red-600/20 text-red-500' : 'text-gray-600 hover:text-white'}`}
            title="Retail"
          >
            <User size={24} />
          </button>
        </div>

        <div className="mt-8 lg:mt-12 flex lg:flex-col gap-4 border-t border-white/5 pt-8">
           {[Language.EN, Language.ZH, Language.RU].map(l => (
             <button 
                key={l}
                onClick={() => setLang(l)}
                className={`text-[10px] font-black w-10 h-10 rounded-full flex items-center justify-center border transition-all ${lang === l ? 'bg-white/10 border-white/30 text-white' : 'border-transparent text-gray-600 hover:text-gray-400'}`}
             >
               {l}
             </button>
           ))}
        </div>

        <div className="mt-auto hidden lg:flex flex-col gap-6">
          <button 
            onClick={() => setActiveView(ViewState.MARKET_SURFACE)} 
            className={`p-4 transition-all ${activeView === ViewState.MARKET_SURFACE ? 'text-blue-400' : 'text-gray-600 hover:text-white'}`}
            title={t.nav_surface}
          >
            <Grid size={22}/>
          </button>
          <button 
            onClick={() => setActiveView(ViewState.TECHNICAL)} 
            className={`p-4 transition-all ${activeView === ViewState.TECHNICAL ? 'text-blue-400' : 'text-gray-600 hover:text-white'}`}
            title={t.nav_quant}
          >
            <Layers size={22}/>
          </button>
          <button 
            onClick={() => setActiveView(ViewState.GRAPH)} 
            className={`p-4 transition-all ${activeView === ViewState.GRAPH ? 'text-blue-400' : 'text-gray-600 hover:text-white'}`}
            title={t.nav_topology}
          >
            <Network size={22}/>
          </button>
          <button 
            onClick={() => setActiveView(ViewState.MEMPOOL)} 
            className={`p-4 transition-all ${activeView === ViewState.MEMPOOL ? 'text-blue-400' : 'text-gray-600 hover:text-white'}`}
            title="Mempool Scanner"
          >
            <Zap size={22}/>
          </button>
        </div>
      </nav>

      {/* DASHBOARD AREA */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">

        {/* HEADER */}
        <header className="h-20 border-b border-white/5 flex items-center px-10 justify-between bg-black/20 backdrop-blur-md">
          <div className="flex items-center gap-6">
            <h1 className="text-xs font-black uppercase tracking-[0.4em] text-gray-500">
              {userMode === UserMode.INSTITUTIONAL ? t.title_inst : t.title_retail}
            </h1>
            <div className="flex items-center gap-4 ml-6 border-l border-white/10 pl-6">
               <div className="flex items-center gap-2">
                  <Database size={14} className="text-gray-600" />
                  <span className="text-[10px] font-black uppercase text-gray-500">
                    {userMode === UserMode.INSTITUTIONAL ? t.network_inst : t.network_retail}
                  </span>
               </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <form onSubmit={handleSearch} className="relative group">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 flex items-center gap-2">
                 {isSearching ? <RefreshCw size={14} className="text-blue-500 animate-spin" /> : <Search size={14} className="text-gray-500 group-focus-within:text-blue-500" />}
              </div>
              <input 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Contract Discovery (Multi-Chain)..." 
                className="bg-white/5 border border-white/10 rounded-xl py-2 pl-10 pr-4 text-[11px] mono focus:border-blue-600 outline-none w-80 transition-all"
                disabled={isSearching}
              />
            </form>

            {currentToken && (
              <div className="flex items-center gap-6 animate-fade-in">
                <div className="text-right">
                  <div className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">
                    {currentToken.symbol} / USD
                    {currentToken.chain && <span className="ml-2 text-blue-500 px-1.5 py-0.5 bg-blue-500/10 rounded uppercase">{currentToken.chain}</span>}
                  </div>
                  <div className="text-xl font-black mono text-green-400">${formatPrice(currentToken.priceUsd)}</div>
                </div>
                <img src={currentToken.image} className="w-10 h-10 rounded-full border border-white/10" />
              </div>
            )}
          </div>
        </header>

        {/* WORKSPACE CONTENT */}
        <div className="flex-1 p-8 grid grid-cols-12 gap-8 overflow-y-auto scrollbar-hide">

          <div className="col-span-12 lg:col-span-8 flex flex-col gap-8">

            {/* INTELLIGENCE BAR */}
            {currentToken && (
              <div className="grid grid-cols-4 gap-4">
                 {[
                   { label: 'Asset Sector', value: currentToken.sector || 'DeFi', icon: <Grid size={12}/>, source: 'MESSARI' },
                   { label: 'Volatility Index', value: `${(currentToken.volatility || 0.5).toFixed(2)}σ`, icon: <Activity size={12}/>, source: 'MESSARI' },
                   { label: 'Market Dominance', value: `${(currentToken.dominance || 0).toFixed(2)}%`, icon: <TrendingUp size={12}/>, source: 'MESSARI' },
                   { label: 'MM Activity', value: currentToken.mktMakerActivity || 'HIGH', icon: <Database size={12}/>, source: 'WINTERMUTE' }
                 ].map((metric, i) => (
                   <div key={i} className="bg-[#0a0a0a] border border-white/5 p-4 rounded-2xl flex flex-col gap-2 group hover:border-indigo-500/30 transition-all">
                      <div className="flex justify-between items-center">
                         <div className="p-1.5 bg-white/5 rounded-lg text-gray-500 group-hover:text-indigo-400 transition-colors">
                            {metric.icon}
                         </div>
                         <span className="text-[7px] font-black px-1.5 py-0.5 bg-white/5 text-gray-500 rounded uppercase tracking-widest">{metric.source}</span>
                      </div>
                      <div>
                         <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest">{metric.label}</span>
                         <div className="text-sm font-black text-white uppercase tracking-tight">{metric.value}</div>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {activeView === ViewState.MARKET_SURFACE && (
              <div className="bg-[#0a0a0a] rounded-[32px] border border-white/5 overflow-hidden flex flex-col h-[650px] shadow-2xl">
                 <div className="p-6 border-b border-white/5 flex justify-between items-center bg-black/40">
                   <h2 className="text-[11px] font-black uppercase tracking-[0.2em] flex items-center gap-3 text-blue-500">
                     <Binary size={16}/> {userMode === UserMode.INSTITUTIONAL ? "Institutional Liquidity Surface" : "Retail Market Pulse"}
                   </h2>
                   <div className="flex items-center gap-4">
                      <div className="flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
                         <span className="text-[9px] font-black text-gray-500 uppercase">REAL-TIME LD4 SCANNER</span>
                      </div>
                   </div>
                 </div>
                 <div className="flex-1 overflow-y-auto">
                    <table className="w-full text-left border-collapse">
                      <thead className="sticky top-0 bg-[#0a0a0a] z-10 text-[9px] uppercase text-gray-600 border-b border-white/5 font-black">
                        <tr>
                          <th className="p-5">Asset</th>
                          <th className="p-5">Price</th>
                          <th className="p-5">24h Change</th>
                          <th className="p-5">Market Cap</th>
                          <th className="p-5 text-right">Action</th>
                        </tr>
                      </thead>
                      <tbody className="text-xs mono">
                        {marketSurface.map((token) => (
                          <tr 
                            key={token.id} 
                            onClick={() => handleTokenSelect(token)}
                            className={`border-b border-white/5 transition-all cursor-pointer ${currentToken?.id === token.id ? 'bg-blue-600/10 border-blue-500/20' : 'hover:bg-white/5'}`}
                          >
                            <td className="p-5 flex items-center gap-4">
                              <img src={token.image} className="w-7 h-7 rounded-full" />
                              <div className="font-black text-white">{token.symbol}</div>
                            </td>
                            <td className="p-5 font-bold">${formatPrice(token.priceUsd)}</td>
                            <td className={`p-5 font-black ${(token.priceChange24h || 0) >= 0 ? 'text-green-500' : 'text-red-500'}`}>
                              {(token.priceChange24h || 0).toFixed(2)}%
                            </td>
                            <td className="p-5 text-gray-400">${(token.marketCap / 1e9).toFixed(2)}B</td>
                            <td className="p-5 text-right"><ChevronRight size={16} className="ml-auto text-gray-700" /></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                 </div>
              </div>
            )}

            {activeView === ViewState.TECHNICAL && (
              <div className="flex flex-col gap-8 h-full">
                <div className="grid grid-cols-2 gap-8 h-[500px]">
                  <RetinaDisplay data={mempool.map(t => t.gasPrice)} type="GAF" />
                  <div className="bg-[#0a0a0a] rounded-[32px] border border-white/5 overflow-hidden flex flex-col p-6">
                    <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-6 flex items-center gap-2">
                      <Target size={14}/> L3 Liquidity Depth
                    </h3>
                    <LiquidityHeatmap 
                      bids={Array.from({length: 10}, (_, i) => ({ price: (currentToken?.priceUsd || 100) - i*0.1, size: Math.random() * 10, isAnomalous: Math.random() > 0.8 }))} 
                      asks={Array.from({length: 10}, (_, i) => ({ price: (currentToken?.priceUsd || 100) + i*0.1, size: Math.random() * 10, isAnomalous: Math.random() > 0.8 }))} 
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="bg-[#0a0a0a] rounded-[24px] border border-white/5 p-6 shadow-xl relative overflow-hidden group">
                     <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest block mb-1">Wyckoff Phase</span>
                     <div className="text-xl font-black text-white">{techData?.marketStructure || 'SCANNING...'}</div>
                  </div>
                  <div className="bg-[#0a0a0a] rounded-[24px] border border-white/5 p-6 shadow-xl relative overflow-hidden">
                     <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest block mb-1">OB Imbalance</span>
                     <div className="text-xl font-black text-white">{((techData?.obImbalance || 0) * 100).toFixed(1)}%</div>
                  </div>
                  <div className="bg-[#0a0a0a] rounded-[24px] border border-white/5 p-6 shadow-xl relative overflow-hidden">
                     <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest block mb-1">Institutional LPE</span>
                     <div className="text-xl font-black text-blue-500">{report?.lpe_rating || '---'}%</div>
                  </div>
                </div>
              </div>
            )}

            {activeView === ViewState.GRAPH && (
              <div className="h-[650px] bg-[#0a0a0a] rounded-[32px] border border-white/5 overflow-hidden shadow-2xl flex flex-col relative">
                 <div className="p-6 border-b border-white/5 flex justify-between items-center bg-black/40 z-20">
                   <div className="flex flex-col gap-1">
                    <h2 className="text-[11px] font-black uppercase tracking-[0.2em] flex items-center gap-3 text-blue-500">
                      <Network size={16}/> {userMode === UserMode.INSTITUTIONAL ? "Arkham Entity Topology" : "Social Alpha Graph"}
                    </h2>
                    <span className="text-[8px] text-gray-500 mono uppercase">Flow Data Aggregator</span>
                   </div>
                 </div>
                 <div className="flex-1">
                    <WalletGraph data={walletData} />
                 </div>
              </div>
            )}

            {activeView === ViewState.MEMPOOL && (
               <MempoolVisualizer data={mempool} />
            )}
          </div>

          <div className="col-span-12 lg:col-span-4 flex flex-col gap-8">

            {/* MODE-SPECIFIC FEED PANEL */}
            <div className="bg-[#0a0a0a] border border-white/5 rounded-[40px] p-8 shadow-2xl overflow-hidden flex flex-col max-h-[440px]">
               <div className="flex justify-between items-center mb-6">
                  <div className="flex items-center gap-3">
                     <div className={`p-2 rounded-xl ${userMode === UserMode.INSTITUTIONAL ? 'bg-indigo-500/10 text-indigo-400' : 'bg-red-500/10 text-red-500'}`}>
                        {userMode === UserMode.INSTITUTIONAL ? <ListFilter size={18} /> : <TrendingUp size={18} />}
                     </div>
                     <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-gray-400">
                        {userMode === UserMode.INSTITUTIONAL ? t.feed_inst_title : t.feed_retail_title}
                     </h2>
                  </div>
                  <span className={`text-[8px] font-black px-2 py-0.5 rounded border ${userMode === UserMode.INSTITUTIONAL ? 'text-indigo-400 bg-indigo-400/10 border-indigo-500/20' : 'text-red-400 bg-red-400/10 border-red-500/20'}`}>
                    {userMode === UserMode.INSTITUTIONAL ? 'SOVEREIGN' : 'ALPHA_PULSE'}
                  </span>
               </div>

               <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                  {transfers.length === 0 ? (
                    <p className="text-[10px] text-gray-600 italic text-center py-10">
                      {userMode === UserMode.INSTITUTIONAL ? t.feed_inst_desc : t.feed_retail_desc}
                    </p>
                  ) : (
                    transfers.map(t_item => (
                      <div 
                        key={t_item.id} 
                        onClick={() => setSelectedTransfer(t_item)}
                        className={`p-4 bg-white/5 rounded-2xl border border-white/5 group hover:bg-white/10 transition-all cursor-pointer ${selectedTransfer?.id === t_item.id ? (userMode === UserMode.INSTITUTIONAL ? 'border-indigo-500 bg-indigo-500/5' : 'border-red-500 bg-red-500/5') : ''}`}
                      >
                         <div className="flex justify-between items-start mb-2">
                            <span className={`text-[9px] font-black uppercase tracking-widest ${userMode === UserMode.INSTITUTIONAL ? 'text-indigo-400' : 'text-red-400'}`}>
                              {t_item.entity}
                            </span>
                            <span className="text-[8px] text-gray-600 mono">{t_item.time}</span>
                         </div>
                         <div className="flex items-center gap-3 mb-2">
                            <div className={`w-1.5 h-1.5 rounded-full ${userMode === UserMode.INSTITUTIONAL ? 'bg-indigo-500' : 'bg-red-500'}`} />
                            <p className="text-[10px] text-gray-300 font-bold">
                              {userMode === UserMode.INSTITUTIONAL ? `Trace: ${t_item.from.split(':')[0]} → Wallet` : `Alert: ${t_item.from}`}
                            </p>
                         </div>
                         <div className="flex justify-between items-center">
                            <span className="text-[11px] font-black text-white mono">
                              {userMode === UserMode.INSTITUTIONAL ? `$${(t_item.amount || 0).toLocaleString()} ${t_item.symbol}` : `HEAT: +${((t_item.amount || 0) / 100).toFixed(0)}%`}
                            </span>
                            <span className="text-[7px] font-black px-1.5 py-0.5 bg-white/5 text-gray-500 rounded uppercase tracking-tighter">
                              {userMode === UserMode.INSTITUTIONAL ? "DPI Available" : t_item.sentiment}
                            </span>
                         </div>
                      </div>
                    ))
                  )}
               </div>

               {selectedTransfer && (
                 <div className={`mt-4 p-5 rounded-3xl animate-pop-in relative border ${userMode === UserMode.INSTITUTIONAL ? 'bg-indigo-600/10 border-indigo-500/20' : 'bg-red-600/10 border-red-500/20'}`}>
