                      <Hash size={12} className={userMode === UserMode.INSTITUTIONAL ? 'text-indigo-400' : 'text-red-400'} /> 
                      {userMode === UserMode.INSTITUTIONAL ? "Deep Packet Inspection" : "Social Alpha Breakdown"}
