                  <input 
                    type="number" 
                    value={maxVal}
                    onChange={(e) => setMaxVal(e.target.value)}
                    placeholder="∞"
                    className="w-12 bg-transparent text-[9px] text-white font-mono focus:outline-none text-right"
                  />
               </div>
            </div>
         </div>

         {/* List */}
         <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
